/** Denník zmien (najnovšie hore). */
function mysn_changelog() {
	return array(
		array( '0.15.0', '14. 11. 2026', 'My Snooker je samostatný projekt na GitHube (Aveyona/my-snooker), súčasť rodiny My. Vývoj prebieha tam, na web hedlajner.sk sa preberá do repozitára doplnkov My. Doplnky My Users, My Chat, My Rooms, My AI Writer a My Player sú povinnou súčasťou hry – WordPress My Snooker bez nich nezapne a kým je hra zapnutá, nedovolí ich vypnúť.' ),
		array( '0.14.9', '14. 11. 2026', 'Keď hráč dosiahne rozhodujúci náskok (súper by už potreboval snookery), publikum mu zatlieska (veľký potlesk) a Rudo po potlesku povie niečo vtipné k partii (živý komentár s menami a skóre, inak nový zvuk Rozhodujúci náskok). Rudo teraz vždy počká, kým potlesk alebo ovácie doznejú, a až potom prehovorí.' ),
		array( '0.14.8', '14. 11. 2026', 'Publikum a Rudo: Ako často Rudo hovorí má štyri možnosti: menej (asi o polovicu), normálne, viac (skoro pri každej príležitosti) a len dôležité chvíle. Séria 50, stovka a koniec framu a zápasu zaznejú vždy.' ),
		array( '0.14.7', '14. 11. 2026', 'Nastavenia publika a Ruda sa presunuli z hry do administrácie: nová stránka My Snooker → Publikum a Rudo (Rudo zapnutý, popis postavy, hlasitosť, ako často hovorí, odstup medzi komentármi, živé komentáre a ich limit za hodinu, potlesk, potlesk za sériu od koľkých bodov, reakcie publika). Platia pre všetkých hráčov a divákov. V hre ostali Nastavenia ako predtým (bez záložiek).' ),
		array( '0.14.6', '14. 11. 2026', 'Nastavenia majú dve záložky: Hra a zvuk a Publikum a Rudo. Na záložke Publikum a Rudo: hlasitosť divákov, potlesk (ako v snookri alebo vypnutý), reakcie publika (óóó, jooooj, smiech, kašľanie), popis postavy Ruda, Rudo zapnutý (sedí na tribúne a komentuje), hlasitosť Ruda, ako často hovorí (často alebo len dôležité chvíle) a živé komentáre podľa situácie (bez nich hrá pripravené repliky).' ),
		array( '0.14.5', '14. 11. 2026', 'Potlesk ako v skutočnom snookri: po potopenej červenej sa netlieska (pri ťažkej červenej z mantinelu len óóó), po farebnej guli zdvorilý potlesk, keď séria 20 a viac bodov skončí, veľký potlesk (od 50 ovácie), stovka ovácie hneď a koniec framu veľké ovácie po hlásení rozhodcu.' ),
		array( '0.14.4', '14. 11. 2026', 'Rudo hovorí u všetkých tú istú vetu: zo zásoby replík sa predtým u každého hráča a diváka vyberal iný náhodný variant. Teraz variant určí strelec (pri páde gule a rozložení gúľ sa vyberie podľa polôh gúľ), rovnako aj nahrávku potlesku.' ),
		array( '0.14.3', '14. 11. 2026', 'Potlesk a reakcie publika sú v zápase pre všetkých rovnaké: predtým ich počul len strelec (súper a diváci nie alebo inak). Teraz reakciu (potlesk, ovácie pri stovke, óóó a potlesk po guli z mantinelu, jooooj pri guli na hrane, smiech) určí strelec a ide so stavom zápasu, takže ju súper aj diváci počujú v tej istej chvíli ako hlásenie rozhodcu.' ),
		array( '0.14.2', '14. 11. 2026', 'Rudo pri faule častejšie rezignuje: Idem asi radšej fajčiť, idem na pivo, idem domov, zobudíte ma, keď sa začne hrať snooker a podobne (nové repliky Faul, Biela v jamke a Minutie, aj živé komentáre k faulu).' ),
		array( '0.14.1', '14. 11. 2026', 'Rudo hovorí aj pomedzi zápas: občas vykríkne hneď, keď guľa spadne do jamky (ešte kým sa gule gúľajú), a po údere okomentuje zaujímavé rozloženie gúľ na stole: posledná červená, už len čierna, guľa visí nad jamkou, biela prilepená na mantineli, kopa červených (každú situáciu raz za frame). Náhoda sa počíta z polôh gúľ, takže hráči aj diváci počujú to isté. Nové zvuky skupiny Komentátor Rudo: Guľa padá, Posledná červená, Len čierna, Guľa visí nad jamkou, Biela na mantineli, Kopa červených.' ),
		array( '0.14.0', '14. 11. 2026', 'Rudo komentuje častejšie (nie každý ťah: bežnú potopenú guľu asi v 40 %, minutie v polovici prípadov, nový zvuk Potopená guľa), hlasnejšie a s intonáciou podľa situácie: nadšene pri sérii a peknom údere, nahnevane pri faule, so vzdychom pri smole, napäto pri frame balle (model v3 dostane značku emócie, ostatné výraznejší prednes). Živé komentáre sú častejšie a Rudo sa v nich stále snaží robiť srandu. Popis Ruda sa upravuje v Zvukoch pri skupine Komentátor Rudo, AI sa ním riadi a hráč ho vidí v Nastaveniach (Kto je divák Rudo).' ),
		array( '0.13.6', '14. 11. 2026', 'Rudo sa neprekrýva s divákmi ani s rozhodcom: kým hovorí, potlesk, reakcie publika a zvuky divákov sa stíšia na tretinu a potom sa plynulo vrátia; prehovorí až po dohovorení rozhodcu a dve jeho vety nejdú cez seba. Jeho hlas nezávisí od hlasitosti divákov v Nastaveniach.' ),
		array( '0.13.5', '14. 11. 2026', 'Oprava: živý komentár Ruda počul len ten, kto ho dal vygenerovať; ostatní (súper, diváci) čakali na rovnakú nahrávku, ale server im kvôli medzipamäti vždy odpovedal, že ešte nie je hotová. Teraz generuje len prvý (atómový zámok) a ostatní dostanú tú istú nahrávku, takže všetci počujú to isté. Náhradná replika zaznie až po 20 s a len keď je vygenerovaná.' ),
		array( '0.13.4', '14. 11. 2026', 'Rozhodcu a Ruda počujú aj diváci ligového zápasu (predtým len hráči): hlásenie k úderu ide divákom so stavom zápasu a zaznie, keď gule dobehnú. Čo Rudo povie, rozhodne strelec raz pre všetkých, takže hráči aj diváci počujú to isté (živý komentár je pre všetkých jedna nahrávka).' ),
		array( '0.13.3', '14. 11. 2026', 'Rudo komentuje viac podľa situácie: séria 50, stovka, koniec framu a zápasu vždy naživo (AI napíše vetu s menami, skóre, sériou a stavom vo framoch, ElevenLabs ju namluví), občas naživo aj faul (hlavne keď sa pomýli vedúci hráč), biela v jamke, potrebné snookery, frame ball, pekný úder a guľa na hrane; inak hrá zo zásoby replík. Najviac 60 živých komentárov za hodinu, pri chybe náhradná replika.' ),
		array( '0.13.2', '14. 11. 2026', 'Hlasy rozhodcu a Ruda sa načítajú hneď po zvukoch stola (predtým až na konci, takže na začiatku hry chvíľu mlčali) a na načítanie repliky sa čaká dlhšie.' ),
		array( '0.13.1', '14. 11. 2026', 'Komentátor Rudo je vidieť: celý v čiernom, čierne zrkadlové okuliare a dlhé biele vlasy, sedí sám v strede tretieho radu na strane rozhodcu (stoličky vedľa neho sú pre online divákov obsadené). Hovorí z tohto miesta; pri pekných momentoch vstane a tlieska, pri chybách sa chytí za hlavu. Keď si ho hráč v Nastaveniach vypne, na tribúne nesedí.' ),
		array( '0.13.0', '14. 11. 2026', 'Komentátor Rudo: divák na tribúne štadióna, ktorý po slovensky a s humorom komentuje ligový zápas: začiatok, faul, biela v jamke, minutie, guľa na hrane, pekný úder, séria 50, koniec framu (náhodný variant zo zvukov skupiny Komentátor Rudo; v administrácii Zvuky každý riadok textu = jeden vygenerovaný variant, vlastný výber hlasu). Stovku a koniec zápasu komentuje naživo: AI napíše vetu s menami a skóre a ElevenLabs ju namluví (pri chybe hrá náhradný zvuk). Hlas ide z jeho miesta na tribúne, hovorí najviac raz za 6 sekúnd a až po rozhodcovi. Hráč ho vypne v Nastaveniach (Komentátor Rudo na štadióne).' ),
		array( '0.12.3', '13. 11. 2026', 'Rozhodca a diváci hovoria len po anglicky (zápas je medzinárodný): hlasy sa generujú po anglicky, aj mená hráčov („Robertson to break.“), slovenské súbory sa v hre nehrajú. V Nastaveniach je Hlas rozhodcu zapnutý alebo vypnutý.' ),
		array( '0.12.2', '13. 11. 2026', 'Zvuky a hlas rozhodcu na jednej stránke Zvuky (záložka Hlas rozhodcu zrušená). Pri každom zvuku tlačidlo Generovať…: hlasy (rozhodca, Well done) cez ElevenLabs z textu po slovensky alebo anglicky, ostatné zvuky ako zvukový efekt ElevenLabs z anglického popisu (dĺžka, slučka); vygenerovaný súbor pribudne do galérie zvuku ako ďalší variant (Hrá, priorita, doladenie). Hlas na generovanie sa vyberá pri skupine Rozhodca a Diváci (s ukážkou a modelom). Nové zvuky rozhodcu: frame ball, potrebné snookery, čierna späť na spot a čísla série 1 až 147 (zbalená skupina s hromadným generovaním). Súbory s jazykom v názve hrajú podľa nastavenia hráča Hlas rozhodcu; repliky zo starej záložky sa presunuli do galérií.' ),
		array( '0.12.1', '13. 11. 2026', 'Hlas rozhodcu sa presunul do administrácie Zvuky ako záložka Hlas rozhodcu (generovaný), vedľa záložky Zvuky a nahrávky. Hlas na generovanie sa dá vybrať zo všetkých hlasov účtu ElevenLabs (aj klony) s ukážkou, plus model; prázdny výber = klon z My Rooms. Repliky a mená hráčov vygenerované iným hlasom sa označia a Vygenerovať chýbajúce ich vytvorí znova.' ),
		array( '0.12.0', '13. 11. 2026', 'Hlas rozhodcu: repliky sa generujú cez ElevenLabs Robovým hlasom (klon z My Rooms) po slovensky aj anglicky, v administrácii My Snooker → Hlas rozhodcu (texty sa dajú upraviť, generuje sa po jednej alebo všetky chýbajúce naraz). Hráč si v Nastaveniach vyberie Hlas rozhodcu: slovensky, anglicky alebo vypnutý. Nové hlásenia: body v sérii po každej potopenej guli (aj v hre o skóre), frame ball, potrebné snookery, čierna späť na spot pri remíze a na začiatku zápasu meno hráča, ktorý rozbíja (vygeneruje sa pri prvom zápase hráča). Repliky idú za sebou, neprekrývajú sa; bez vygenerovanej repliky hrá nahrávka zo Zvukov.' ),
		array( '0.11.2', '13. 11. 2026', 'Ochrana proti podvádzaniu 4: server pri overovaní zbiera štatistiku dlhých úderov (prvá trafená guľa ďalej ako 1,2 m a či spadla) z partií aj z hry o skóre. Administrácia Overenie skóre ukazuje úspešnosť každého hráča za 60 dní; nezvyčajne vysoká úspešnosť (80 % a viac pri aspoň 15 úderoch) sa zvýrazní na posúdenie, nikto sa neblokuje.' ),
		array( '0.11.1', '13. 11. 2026', 'Ochrana proti podvádzaniu v lige a partiách cez internet: po každom údere server (overovač) úder prehrá zo stavu, ktorý má uložený, a porovná výsledok so stavom od strelca. Pri nezhode platí stav servera: oba prehliadače aj diváci sa zosúladia a rozhodca to oznámi. Údery, ktoré sa na serveri nedajú prehrať (napr. strieľa, kto nie je na rade), sa označia správcovi; prehľad je v administrácii Overenie skóre.' ),
		array( '0.11.0', '13. 11. 2026', 'Ochrana proti podvádzaniu v hre o najlepšie skóre: hra zapisuje každý úder, po dohraní framu ho server (overovač na live.hedlajner.sk) celý prehrá tým istým kódom fyziky a pravidiel a do rebríčka ide jeho výsledok (✓ Overené serverom). Nepotvrdené framy do rebríčka nejdú a správca ich vidí v administrácii Overenie skóre (schváliť, zamietnuť, overiť znova). Pri výpadku overovača výsledok čaká a overí sa neskôr. Staršie výsledky majú štítok neoverené.' ),
		array( '0.10.6', '13. 11. 2026', 'Mobil: mierenie a úder prstom konečne fungujú – hra na dotykovej obrazovke zachytávala kurzor ako pri myši a prehliadač potom posielal polohu prsta stále 0, 0. Pri dotyku sa kurzor nezachytáva.' ),
		array( '0.10.5', '13. 11. 2026', 'Mobil, úder prstom ako myšou: prst na stole chytí tágo, ťahom dole a hore ide tágo s prstom (aj viackrát dozadu a dopredu), úder nastane, keď tágo dôjde k bielej. Keď sa prst pri švihnutí zdvihne skôr, úder sa dokončí silou švihnutia; pustenie v pokoji úder zruší. Zvislý ťah sa rozpozná ľahšie.' ),
		array( '0.10.4', '13. 11. 2026', 'Telefón na barovom stolíku (Môj účet): okno telefónu po otvorení ostane na mieste (predtým odplávalo a zmizlo – rovnaká chyba s názvom animácie ako pri okne so skóre).' ),
		array( '0.10.3', '13. 11. 2026', 'Hra o najlepšie skóre: okno Gratulujem! s dosiahnutým skóre, časom a miestom v rebríčku po dohraní framu ostane na obrazovke (predtým po chvíli zmizlo a padali len konfety – dve animácie mali rovnaký názov).' ),
		array( '0.10.2', '13. 11. 2026', 'Chat v hre: zmazané správy a správy vymazané po čase sa neukazujú (predtým ostalo len meno s prázdnym riadkom); správa zmazaná v chate zmizne z okna aj počas hry.' ),
		array( '0.10.1', '13. 11. 2026', 'Mobil a tablet: za tágom ťahaj prstom vodorovne = mierenie, dole = odtiahneš tágo, rýchlo hore = úder (sila podľa rýchlosti švihnutia, pustenie bez úderu ho zruší). Dvoma prstami od seba a k sebe priblížiš pohľad (aj v pohľade z kresla). Pri prvom dotyku sa ukáže krátky návod.' ),
		array( '0.10.0', '13. 11. 2026', 'Chat zápasu: počas partie (aj mimo ligy), pri sledovaní a v otvorenej herni má chat v hre dve záložky – 🎱 Zápas (len hráči a diváci tejto partie, zelené správy, divák je označený, po konci partie zmiznú) a Snooker (spoločná miestnosť). Tab v políčku na písanie prepína, kam píšeš. Výzva z webového chatu: v profile hráča, ktorý je práve v hre, je tlačidlo 🎱 Vyzvať na partiu – otvorí hru a pošle mu pozvánku.' ),
		array( '0.9.6', '10. 11. 2026', 'Štadión: svietidlo s obrazovkami nad stolom visí o 40 cm vyššie, aby nezavadzalo kamere za tágom.' ),
		array( '0.9.5', '10. 11. 2026', 'Chat pre divákov: divák na svojom mieste (tribúna na štadióne, miesto v herni) aj v ukážke od diváka otvorí písanie Enterom ako hráč.' ),
		array( '0.9.4', '10. 11. 2026', 'Ukážka od diváka (admin, tribúna na štadióne): skryté hráčske ovládanie, ktoré divák nemá vidieť (guľa Miesto úderu so stavom špice a kriedy vľavo dole, ukazovateľ sily, spodná lišta tréningu), ako pri skutočnom sledovaní.' ),
		array( '0.9.3', '8. 11. 2026', 'Chat v hre: po Enter sa políčko na písanie zavrie hneď, správa sa ukáže bledšie ako odosielaná a po potvrdení servera normálne; keď sa odoslať nedá, políčko sa znova otvorí aj s textom a dôvodom.' ),
		array( '0.9.2', '8. 11. 2026', 'Chat v hre (miestnosť Snooker z doplnku My Chat): Enter otvorí políčko na písanie, Enter pošle, Esc zavrie. Správy sú vľavo: prvá hore, ďalšie pod ňou, najnovšia vždy dole; keď siahnu po stred obrazovky, chat nižšie nejde a staré správy miznú hore. Políčko na písanie je hneď pod poslednou správou (bez správ hore vľavo). Nové správy prídu okamžite cez live server. Pri bielej v ruke, v pohľadoch (kreslo, noviny, stojan s tágami a ďalšie), v okne nájdeného zápasu a na konci partie má Enter doterajší význam.' ),
		array( '0.9.1', '8. 11. 2026', 'Lepší prenos cez vlastný server live.hedlajner.sk (Hetzner): server TURN (coturn) sprostredkuje spojenie hráčov aj divákov, keď priame spojenie nejde (prísne siete, mobilní operátori); prihlasovacie údaje sú časovo obmedzené na 24 hodín. Signály spojenia a pozvánky (nová, prijatá, odmietnutá, zrušená) prídu hráčovi okamžite cez websocket do jeho osobného kanála, nemusí čakať na pravidelný dopyt. Pri výpadku servera ide všetko ako predtým.' ),
		array( '0.9.0', '8. 11. 2026', 'Obývačka je odteraz samostatná hra My Rooms (nový doplnok my-rooms, adresa myrooms.hedlajner.sk, kým nie je subdoména, hedlajner.sk/my-rooms). Cedula Obývačka v chodbe a mapa M otvoria jej stránku, dvere obývačky vedú späť do herne. Televízor s kanálmi, kniha s klávesmi a diaľkový ovládač sa presunuli do My Rooms; Sledovať zápas z televízora otvorí My Snooker priamo ako divák.' ),
		array( '0.8.14', '8. 11. 2026', 'Cedule Kancelária a Obývačka sú späť v chodbe: visia na retiazkach hneď za dverami herne, takže cez otvorené dvere (F6) ich vidno spredu aj zboku; Ctrl a klik na ceduľu prejde do miestnosti.' ),
		array( '0.8.13', '8. 11. 2026', 'Cedule Kancelária a Obývačka sú teraz jemne podsvietené priamo na dverách herne (zo strany herne), vidno ich aj pri zatvorených dverách; Ctrl a klik na ceduľu prejde do miestnosti.' ),
		array( '0.8.12', '8. 11. 2026', 'Kamera: červená čiara v grafe (sledovanie smeru mierenia a zastavenie otáčania kamery) zrušená, kamera pri priblížení sa pozerá na mierenú guľu ako predtým. Graf ostáva: výška kamery, pásma rýchlosti, najbližšie ku guli.' ),
		array( '0.8.11', '8. 11. 2026', 'Kamera, červená čiara v grafe zmenená podľa Roba: od čiary kamera prestane sledovať mierenú guľu a ostane otočená presne tak, ako bola na čiare, ďalej sa len približuje (guľa sa posúva v obraze, jamku za ňou vidno). Šúpatko Ako veľmi sleduje smer mierenia zrušené, Podľa náčrtu dá čiaru na 30 %.' ),
		array( '0.8.10', '8. 11. 2026', 'Administrácia Kamera: červená čiara v grafe priblíženia určuje, odkedy sa kamera prestane pozerať len na mierenú guľu a začne sledovať aj smer mierenia (za guľu, kam po údere pôjde); šúpatko Ako veľmi sleduje smer mierenia (predvolene 70 %), červená plocha v grafe ukazuje, ako sa to postupne zväčšuje. Predvolene vypnuté, tlačidlo Podľa náčrtu ho nastaví od 80 % priblíženia.' ),
		array( '0.8.9', '8. 11. 2026', 'Oprava: priblíženie pravým tlačidlom k vzdialenej guli sa zastavilo v polovici (obmedzenie na dĺžku tága z 0.8.8 platilo aj pri približovaní). Obmedzenie teraz platí len pri ťahaní dozadu.' ),
		array( '0.8.8', '8. 11. 2026', 'Kamera pri držaní pravého tlačidla: oddialenie dozadu (aj posun bez mierenej gule) je obmedzené, kamera nesmie ujsť ďalej od bielej ako je dĺžka tága (s predĺžením) a nesmie vyletieť vysoko nad stôl; pri hranici sa ďalej nevzďaľuje, takže sa netreba dlho vracať.' ),
		array( '0.8.7', '8. 11. 2026', 'Administrácia Kamera: popis k tlačidlám (pridať a odobrať pásmo, podľa náčrtu, predvolené), k šúpatku Najbližšie ku guli (s príkladom) a k náhľadu z boku; v náhľade popisky mierená guľa, kamera za tágom a najbližšie; v úzkom pásme rýchlosti sa text skráti, aby sa neprekrýval.' ),
		array( '0.8.6', '8. 11. 2026', 'Administrácia My Snooker → Kamera: graf, ako funguje priblíženie na mierenú guľu pravým tlačidlom myši. Oranžová krivka je výška kamery počas priblíženia (body sa ťahajú myšou, dvojklik pridá alebo odoberie bod), zelený pás hore je rýchlosť po pásmach (Najrýchlejšie, Rýchlo, Normálne, Pomaly, Najpomalšie; klik zmení rýchlosť, hranice sa ťahajú), šúpatko Najbližšie ku guli a náhľad cesty kamery z boku. Tlačidlá Podľa náčrtu a Predvolené. Platí pre všetkých hráčov.' ),
		array( '0.8.5', '8. 11. 2026', 'Presné mierenie vždy zapnuté je predvolene len pri Citlivom tágu (aj pri vlastnom tágu z jeho šablóny). Pri ostatných tágach so Shift Shift zapína presné mierenie. Doterajšie voľby sa všetkým hráčom raz vynulovali na nové predvolené, na stojane (F2) sa dajú pri každom tágu znova zmeniť.' ),
		array( '0.8.4', '8. 11. 2026', 'Obývačka: F1 priblíži knihu na konferenčnom stolíku, kniha sa otvorí a na stranách sú klávesové skratky obývačky a televízora. Klávesy sa posunuli: F2 televízor, F3 krb, F4 knižnica. Pri televízore (F2) sa vpravo zobrazí diaľkový ovládač: SOURCE prepína zdroj (Snooker: zápasy, záznamy a rekordy; Televízia: živé stanice; YouTube), CH ▲ ▼ kanál (v Televízii priamo ďalšia stanica), VOL + − a stlmenie hlasitosti videa, šípky, OK a Späť. Na klávesnici S, Page Up, Page Down, + a −.' ),
		array( '0.8.3', '8. 11. 2026', 'Televízor v obývačke: nové kanály 4 Televízia (voľné živé spravodajské stanice cez YouTube: Al Jazeera English, DW News, France 24 English, Sky News, euronews, NASA) a 5 YouTube (vložíš odkaz na video, živé vysielanie alebo playlist, posledné pozerané si televízor pamätá). Video hrá priamo na obrazovke televízora, ✕ Zavrieť alebo Esc ho zastaví, odchodom od televízora sa zastaví samo. Kanály sa dajú prepínať aj klávesmi 1 až 5.' ),
		array( '0.8.2', '7. 11. 2026', 'Obývačka, televízor (etapa 2): F1 priblíži televízor a myš je voľná na klikanie po obrazovke. Kanály: 1 Živé zápasy (prebiehajúce ligové zápasy a otvorené partie, klik Sledovať), 2 Moje zápasy (ligové zápasy s výsledkom a ELO, klik Záznam prehrá zápas priamo na televízore s tlačidlami ⏮ ◀ ⏸ ▶▶ ⏭, rýchlosť a Späť), 3 Rekordy (najlepšie brejky z ligy aj hry o skóre a najvyššie ELO). Ovládanie aj klávesmi: ← → kanál, ↑ ↓ výber, Enter spustiť, Esc späť na gauč. Pravé tlačidlo v obývačke už nevracia do herne.' ),
		array( '0.8.1', '7. 11. 2026', 'Chodba: tlmenejšie svetlo a cedule Kancelária a Obývačka, aby nebili do očí (text je lepšie čitateľný).' ),
		array( '0.8.0', '7. 11. 2026', 'Obývačka (etapa 1): z herne cez dvere (F6) do chodby, na jej stene svietiace cedule Kancelária a Obývačka, klik s Ctrl prejde do miestnosti (len prihlásení, neprihláseným cedule nesvietia). Obývačka má gauč, kreslá, krb s plápolajúcim ohňom, koberec, stojaciu lampu, knižnicu, rastliny, okno, hodiny na rímse so skutočným časom a televízor (zatiaľ znelka My Snooker TV). Sedíš na gauči a myšou sa rozhliadaš, F1 televízor, F2 krb, F3 knižnica, Ctrl a klik na dvere späť do herne, v menu Späť do herne, obývačka je aj v mape M. Plán vývoja: nová etapa 7 Obývačka.' ),
		array( '0.7.104', '7. 11. 2026', 'Predĺženie tága už presnosť skoro nekazí: biela náhodne uhne najviac o 0,03° pri 15 cm, 0,06° pri 30 cm a 0,1° pri 45 cm (predtým 0,25°, 0,5° a 0,8°, to sa nedalo hrať). Väčšina úderov ide takmer presne, plná odchýlka príde len výnimočne; silnejší úder trochu viac.' ),
		array( '0.7.103', '7. 11. 2026', 'Voľná kamera: Tab zapne alebo vypne malý náhľad stola zhora vpravo hore (gule vidno, aj keď sa kamera pozerá inam). Nastavenie sa pamätá.' ),
		array( '0.7.102', '7. 11. 2026', 'Zvuk gúľania gúľ po súkne je ešte o niečo tichší.' ),
		array( '0.7.101', '7. 11. 2026', 'Animácia rozhodcu zmenená: po rozostavení rozhodca príde k čiernemu koncu stola, zoberie trojuholník zo súkna, prenesie ho cez mantinel, zvisle ho zavesí pod stôl na jeho háčik a vráti sa na svoje miesto. Admin ju spustí z mapy (M, Štadión, Rozhodca odkladá trojuholník).' ),
		array( '0.7.100', '7. 11. 2026', 'Štadión: animácia rozhodcu, ktorý stavia červené do trojuholníka. Príde k čiernemu koncu stola, po jednej dokotúľa 15 červených do trojuholníka (pravou rukou siaha na stôl), zarovná ich, trojuholník zdvihne a vráti sa na svoje miesto. Admin ju spustí z mapy miestností (M, Štadión, Rozhodca stavia trojuholník). Zvuk gúľania gúľ po súkne je tichší.' ),
		array( '0.7.99', '7. 11. 2026', 'Administrácia Hráči: nové stĺpce percento výhier (z dohraných partií cez internet) a najvyšší break (liga aj hra o skóre), hráči sa dajú zoradiť kliknutím na názov stĺpca (ELO, body, výhry, partie, naposledy v hre a ďalšie).' ),
		array( '0.7.98', '7. 11. 2026', 'Štadión je predvolene ticho: šum publika v pozadí (voľná nahrávka) sa už nepúšťa, hrá len vlastná slučka, ak ju admin vyberie v administrácii Zvuky. Reakcie divákov (potlesk, ovácie, jooooj) ostávajú.' ),
		array( '0.7.97', '7. 11. 2026', 'Štadión: na menovke na stolíku pri kresle je pod menom hráča jeho ELO (vidia to hráči aj diváci).' ),
		array( '0.7.96', '7. 11. 2026', 'ELO sila hráča ako v šachu, len z ligových zápasov: nový hráč začína na 1350, výhra nad silnejším dá viac, nad slabším menej (K 40 prvých 30 zápasov, potom 20), vzdanie a výpadok spojenia sú prehra, zrušený zápas sa neráta. Doterajšie ligové zápasy sa prepočítali spätne. Herňa a kancelária sú bez hukotu: voľné nahrávky miestností (šum klimatizácie) sa už nepúšťajú, je tam ticho, kým admin nenahrá vlastný ambient. ELO je v tabuľke ligy, v notebooku Moja liga, pri konci zápasu (zmena, napríklad 1350 → 1370), v histórii zápasov, v Účte a v administrácii (Hráči, Partie).' ),
		array( '0.7.95', '7. 11. 2026', 'Nešportové správanie v lige: hráč môže v ligovom zápase grgnúť (G) aj prdnúť (H), druhý raz v zápase ho rozhodca napomenie, od tretieho raza dostane súper za každé ďalšie 4 body. Počíta server, napomenutie aj trest vidia a počujú obaja hráči aj diváci; v administrácii Zvuky pribudli hlasy rozhodcu Napomenutie a Trest.' ),
		array( '0.7.94', '7. 11. 2026', 'Administrácia Zvuky: zvuky s vlastnými nahrávkami sú zvýraznené (zelený pás, svetlozelené pozadie a štítok VLASTNÝ ZVUK s počtom zapnutých súborov), navrchu je počet zvukov s vlastnými nahrávkami.' ),
		array( '0.7.93', '7. 11. 2026', 'Zvuky sa načítajú postupne (najprv zvuky stola, potom miestnosť a diváci), server už nedostane naraz stovku požiadaviek (odpovedal 429 Too Many Requests a časť zvukov chýbala).' ),
		array( '0.7.92', '7. 11. 2026', 'Zvuky divákov a hráčov online: divák F2 potlesk, F3 jooooj, 1 jasot, 2 óóó, 3 smiech, 4 pískanie, 5 well done, 6 pšššt, 7 kašeľ (v telefóne F1); hráč v partii N napiť sa vody, G grgnúť, H prdnúť (G a H nie v ligovom zápase). Zvuk počujú obaja hráči aj všetci diváci, ide z miesta, kde divák alebo hráč sedí; najviac jeden zvuk za 2,5 sekundy od jedného človeka.' ),
		array( '0.7.91', '7. 11. 2026', 'Noviny v hre: obrázky článkov z hedlajner.sk sa znova zobrazujú (načítajú sa z adresy hry, prehliadač ich už neblokuje).' ),
		array( '0.7.90', '7. 11. 2026', 'Administrácia Zvuky: tlačidlo Typická situácia pri každom zvuku zahrá zvuk tak, ako zaznie v hre v situácii, pre ktorú je určený (jemný úder slabou silou, tvrdý plnou, rozbitie, jamka pri jamke, rozhodca a diváci na štadióne, ambient vo svojej miestnosti), s klubovým tágom, strednou špicou a kriedou, bez ohľadu na nastavenie skúšky.' ),
				array( '0.7.89', '7. 11. 2026', 'Skúška zvukov: Spôsob Ako v hre: tento zvuk (predvolené) zahrá súbory zvuku presne tak, ako zaznejú v hre pri nastavenej situácii, bez miešania s inými vrstvami; Ako v hre: s ostatnými vrstvami zahrá celý zvuk s prelínaním vrstiev podľa sily; Pôvodný súbor bez úprav. Predtým predvolené prelínanie miešalo aj iné súbory, preto zvuk neznel ako nahrávka.' ),
		array( '0.7.88', '7. 11. 2026', 'Skúška zvukov: Spôsob s možnosťou Pôvodný súbor (bez úprav).' ),
		array( '0.7.87', '7. 11. 2026', 'Administrácia Zvuky: pri každom zvuku odporúčaný názov súboru po anglicky s číslom varianty (napríklad cue-hit-soft-01.wav).' ),
		array( '0.7.86', '7. 11. 2026', 'Základná sada zvukov: ďalších 67 voľných nahrávok (CC0 a public domain): napitie sa vody, grgnutie, prdnutie, jooooj, óóó, šepot, jasot publika, tlkot srdca, znelky začiatku a víťazstva, tiknutie, upozornenie, dvere, jemný a tvrdý náraz gúľ, jemný mantinel. Bez voľnej nahrávky ostáva pšššt, well done, drkotanie v jamke a hlas rozhodcu.' ),
		array( '0.7.85', '7. 11. 2026', 'Body: pri každej potopenej guli vyskočí nad jamkou +1 až +7 vo farbe gule a zaznie zvuk bodov (vyšší pri hodnotnejšej guli; viac gúľ za sebou). Pri faule v partii sa ukáže Faul · súper +4 (až +7). Zvuk Body sa dá nahradiť v administrácii Zvuky (Atmosféra).' ),
		array( '0.7.84', '7. 11. 2026', 'Zvuky: nové zvuky v administrácii a v hre: šepot publika pred rozhodujúcim úderom, jasot a Well done (pre online divákov), skupina Atmosféra: napätie (tlkot srdca pri poslednej čiernej na štadióne, kým sa mieri), znelka pri príchode na štadión, znelka víťazstva (keď nie je označená víťazná skladba), tiknutie časomiery a upozornenie na nájdený zápas; pípnutie pred ťahom hrá nahrávku, ak je.' ),
		array( '0.7.83', '7. 11. 2026', 'Zvuky majú vlastnú galériu My Snooker (priečinok uploads/my-snooker-sounds, mimo knižnice Médií, v Médiách WordPressu sa neukážu ani nepoužívajú). Tlačidlo Súbory… pri zvuku otvorí okno galérie: Pridať súbory (MP3, WAV, OGG, aj viac naraz), pri každom súbore prehrať, Hrá (zapnúť alebo vypnúť) a priorita 1 až 5 (ako často sa hrá oproti ostatným), Odložiť do koša galérie. Základná sada sa po pridaní vlastných súborov vypne (dá sa zapnúť späť). Rádio Hedlajner - Free Music má rovnakú galériu so skladbami (Hrá, víťazná ★).' ),
		array( '0.7.82', '7. 11. 2026', 'Administrácia Zvuky, skúška: ďalšie parametre, s ktorými sa zvuk prehrá ako v hre: výstup (slúchadlá 3D alebo reproduktory), poloha zvuku (pred tebou, vľavo, vpravo, za tebou, ďaleko, bez priestoru), spôsob (ako v hre s vrstvami a situáciou, alebo len súbory zvuku), hmotnosť tága, druh špice, opotrebenie špice, krieda, šmyk, rozbitie, zásah gúľ (plný až tenký) a jamka (rohová, stredná). Tlačidlo Prehrať celý úder zahrá tágo, guľu do gule, mantinel a jamku za sebou. V hre opotrebovaná špica znie tupšie a nižšie.' ),
		array( '0.7.81', '7. 11. 2026', 'Víťazná hudba: skladby rádia Hedlajner - Free Music sa dajú v administrácii Zvuky označiť hviezdičkou. Na konci zápasu na štadióne zahrá všetkým jedna náhodná označená skladba (s prelínaním, hlasitosť podľa nastavenia divákov), pri odchode zo štadióna stíchne.' ),
		array( '0.7.80', '7. 11. 2026', 'Rádio: vlastná stanica Hedlajner - Free Music so skladbami, ktoré admin vyberie v My Snooker → Zvuky (koľko pridá, toľko je na výber). Skladby hrajú zamiešane jedna za druhou, v rádiu je názov práve hranej skladby; stanica je prvá v zozname, hrá priestorovo z reproduktorov. Rádio si pamätá stanicu podľa mena.' ),
		array( '0.7.79', '7. 11. 2026', 'Zvuky: rozhodca hlási (nahrávky po anglicky, na štadióne z jeho miesta) faul aj s bodmi, voľnú guľu, hrá znova, čas, koniec framu a zápasu; hlásenie dostanú hráči aj diváci. Diváci reagujú sami: potlesk po potopenej guli (silnejší od série 30), ovácie pri stovke a na konci framu, óóó a potlesk po guli z mantinelu do jamky, jooooj keď guľa ostane na hrane jamky, smiech keď vedúci hráč (o 20 a viac) zafauluje bez potopenia, občas kašeľ na štadióne. V herni reagujú len keď sedia skutoční diváci.' ),
		array( '0.7.78', '7. 11. 2026', 'Zvuky, etapa Stôl: gúľanie gúľ (šuchot súkna z miesta, kde sa gule gúľajú, hlasitosť, výška a jas podľa rýchlosti, dobeh pri zastavení) a položenie gule (farba na spot, biela z ruky). Plán: animácia rozhodcu s trojuholníkom na začiatku zápasu na štadióne.' ),
		array( '0.7.77', '7. 11. 2026', 'Administrácia Zvuky: pri každom zvuku odporúčaná dĺžka klipu a hlasitosť v klipe (špička v dBFS pri krátkych úderoch, priemer v LUFS pri dlhších zvukoch) a návod, ako ich zmerať. Hlas rozhodcu a divákov je po anglicky.' ),
		array( '0.7.76', '7. 11. 2026', 'Zvuky: základná sada 58 voľných nahrávok (CC0 a royalty free): úder tága, gule, mantinel, jamka, rozbitie, trojuholník, krieda, gúľanie, ambient herne, kancelárie a štadióna, potlesk, údiv, smiech, pískanie, kašeľ. Hrá, kým admin k zvuku nevyberie vlastné súbory; v administrácii Zvuky je pri zvuku vidno základná sada a dá sa prehrať. Zdroje v assets/sounds/LICENSES.txt.' ),
		array( '0.7.75', '7. 11. 2026', 'Zvuky, 1. etapa: nový zvukový engine. Zvuky vznikajú na mieste v scéne a poslucháč je kamera (3D zvuk na slúchadlách, výrazné stereo na reproduktoroch), dozvuk podľa miestnosti (herňa, kancelária, štadión). Úder tága sa mení podľa sily, hmotnosti tága, druhu špice, kriedy, šmyku a rozbitia; gule, mantinel a jamky (rohová, stredná, drkotanie) podľa rýchlosti. Administrácia My Snooker → Zvuky: ku každému z 52 zvukov (stôl, rozostavenie, miestnosti, rozhodca, hráč, diváci) sa vyberajú súbory z Médií (WAV, MP3, OGG, viac súborov = varianty) a dolaďuje hlasitosť, tón, farba, náhodnosť, citlivosť na silu a dozvuk, so skúškou. Zvuk bez súboru hrá generovanú náhradu. Nastavenia hráča: hlasitosť zvukov stola, miestnosti a divákov a Priestorový zvuk (slúchadlá alebo reproduktory).' ),
		array( '0.7.74', '7. 11. 2026', 'Natiahnutý úder (s nádstavcom mimo dosahu): Miesto úderu sa zamkne v strede (sivá guľa, falša sa nedá zadať ani klávesmi), úder ide bez falše a pod guľou je oranžový text Natiahnutý úder ±x°, bez falše.' ),
		array( '0.7.73', '7. 11. 2026', 'Natiahnutý úder: s nádstavcom (krížik alebo pavúk) sa dá hrať aj tam, kam nedosiahneš, ale úder je nepresný. Biela náhodne uhne od 1,5° (predĺženie 45 cm), 2,5° (30 cm), 3,5° (15 cm) až po extrémnych 5° bez predĺženia, a viac podľa toho, o koľko chýba (najviac dvojnásobok), silnejší úder viac. Upozornenie dole je oranžové a ukazuje odklon. Bez nádstavca sa mimo dosahu hrať nedá.' ),
		array( '0.7.72', '7. 11. 2026', 'Tágá so Shift (jemné mierenie): presné mierenie je predvolene vždy zapnuté a Shift prepne na rýchle. Na stojane F2 hneď pod popisom tága sa dá voľba Presné mierenie vždy zapnuté vypnúť (potom Shift zapína presné ako predtým). Pamätá sa pri každom tágu zvlášť.' ),
		array( '0.7.71', '7. 11. 2026', 'Predĺženie tága škodí presnosti stredne: biela náhodne uhne až o 0,25° pri 15 cm, 0,5° pri 30 cm a 0,8° pri 45 cm (silnejší úder viac).' ),
		array( '0.7.70', '7. 11. 2026', 'Predĺženie tága zhoršuje presnosť: biela náhodne uhne až o 0,15° pri 15 cm, 0,3° pri 30 cm a 0,5° pri 45 cm (silnejší úder viac, sčíta sa s nepresnosťou opotrebovanej špice). Nasadené predĺženie je vidno na tágu vľavo dole (tmavý kus s kovovým spojom) a pod guľou Miesto úderu text Predĺženie 30 cm ±0,3°.' ),
		array( '0.7.69', '7. 11. 2026', 'Pravidlá: po súperovom faule voľba Hrám ja (1) alebo Nech hrá súper (2). Súper potom hrá z miesta, kde gule ostali, bez voľnej gule; opakovať sa dá bez limitu, za každý faul sú trestné body. Úderom hráš sám. Platí aj po faule za čas. Výzva na partiu na 1, 3 alebo 5 framov (vyhráva, kto prvý vyhrá väčšinu), ďalší frame rozbíja striedavo, hore stav vo framoch. Liga ostáva na 1 frame.' ),
		array( '0.7.68', '7. 11. 2026', 'Za tágom pravé tlačidlo myši nerobí nič, keď nemieriš na žiadnu guľu (pohľad sa neposúva).' ),
		array( '0.7.67', '7. 11. 2026', 'Kancelária: priblíženie na predmet zruší pravé tlačidlo myši aj bez Ctrl (ako v herni návrat za tágo).' ),
		array( '0.7.66', '7. 11. 2026', 'Oblúk pri priblížení na mierenú guľu je plynulý: rovnomerne s pohybom myši, bez skoku na začiatku a bez ostrého vrcholu.' ),
		array( '0.7.65', '7. 11. 2026', 'Kancelária: Ctrl a pravé tlačidlo myši zruší priblíženie na predmet (notebook, kalendár, tabuľa, nástenka, mapa, stojan) a vráti pohľad za písací stôl.' ),
		array( '0.7.64', '7. 11. 2026', 'Priblíženie na mierenú guľu (pravé tlačidlo, myš hore) ide po oblúku: do polovice priblíženia kamera stúpa, potom pomaly klesá až ku guli.' ),
		array( '0.7.63', '7. 11. 2026', 'Kancelária s držaným Ctrl ako herňa: predmety pod kurzorom sa jemne rozsvietia a klik ich otvorí (nástenka F1, stojan F2, kalendár F3, tabuľa líg F4, notebook F7, vizitka F8, dvere F9, lampa F12, mapa hráčov so špendlíkmi). Tréning z menu v kancelárii neotvorí menu znova.' ),
		array( '0.7.62', '7. 11. 2026', 'Menu v kancelárii: Tréning a Hrať ťa prenesú z kancelárie do herne (predtým sa nič nestalo).' ),
		array( '0.7.61', '7. 11. 2026', 'Kancelária: Esc otvorí menu (predtým presunul do herne). Druhé Esc menu zavrie a ostávaš v kancelárii.' ),
		array( '0.7.60', '7. 11. 2026', 'Keď na bielu nedosiahneš, pri špici tága vedľa gule Miesto úderu bliká červený výkričník (popri upozornení dole).' ),
		array( '0.7.59', '7. 11. 2026', 'Stav špice a kriedy inak: vedľa gule Miesto úderu je koniec tága zboku. Špica má farbu tvojej špice a opotrebením sa zmenšuje, navrchu je vrstva kriedy vo farbe kriedy (hrubšia = viac úderov), nad ním percento špice. Miesto úderu je opäť modrá bodka.' ),
		array( '0.7.58', '7. 11. 2026', 'Miesto úderu sa po každom údere vráti do stredu. Na guli Miesto úderu je v strede čelo špice (farba špice, poprášené kriedou, tmavšie podľa opotrebenia) a okolo dva oblúky: vľavo zdravie špice, vpravo nakriedovanie; pod guľou Špica v % a Krieda 3/3. Detail dotyku je predvolene vpravo dole.' ),
		array( '0.7.57', '7. 11. 2026', 'Herňa F1: väčšia nástenka (2,6 m) so šiestimi papiermi: všetky klávesy aj F3 1 až 7, Ctrl a šúpatká myši, princíp hry, tágá a špice, dosah a pomôcky a obrázok myši s popisom tlačidiel (ľavé, koliesko, pravé, pohyb).' ),
		array( '0.7.56', '7. 11. 2026', 'Ponuka F3: predĺženie tága má dve tlačidlá. Kláves 6 nasadí predĺženie 15 cm a ďalej mení 15, 30, 45 cm; kláves 7 Dať predĺženie dole je samostatné tlačidlo.' ),
		array( '0.7.55', '7. 11. 2026', 'Dosah tága opravený: hráč stojí kdekoľvek pri stole, rozhoduje vzdialenosť rúk od najbližšieho mantinelu. Ruka na mostíku (30 cm za bielou) najviac 95 cm, ruka na rukoväti (3/4 tága za bielou, s predĺžením ďalej) najviac 55 cm od mantinelu alebo už za ním. S krížikom alebo pavúkom len rukoväť (skoro celé tágo za bielou). Úder popri mantineli pozdĺž stola je teda povolený.' ),
		array( '0.7.54', '7. 11. 2026', 'Dosah tága: hráč stojí mimo stola a na bielu dosiahne len podľa dĺžky tága (bez nádstavca asi polovica tága a naklonenie, pri 145 cm asi 1,1 m od okraja stola; s krížikom alebo pavúkom celé tágo a 30 cm, asi 1,75 m). Keď nedosiahne, úder sa nedá zahrať a pri mierení je upozornenie. Predĺženie tága 15, 30 alebo 45 cm (F3, kláves 6): dosah ďalej, ťahanie dlhšie, vidno ho na tágu aj u súpera. Platí všade, aj v lige.' ),
		array( '0.7.53', '7. 11. 2026', 'Tágá s jemným mierením (Shift): na stojane F2 voľba Jemné mierenie vždy zapnuté. Pri zapnutej mieriš stále presne a Shift naopak prepne na rýchle mierenie. Nastavuje sa pri každom tágu zvlášť a pamätá sa.' ),
		array( '0.7.52', '7. 11. 2026', 'Nové šúpatko Pravé tlačidlo (pri držanom Ctrl, 0,3× až 3×): citlivosť pohľadu pravým tlačidlom myši vo všetkých smeroch (krúženie okolo mierenej gule doľava a doprava, priblíženie a oddialenie hore a dole). Pamätá sa.' ),
		array( '0.7.51', '7. 11. 2026', 'Nové šúpatko Ťahanie tága (pri držanom Ctrl vedľa Otáčania myšou, 0,3× až 3×): rýchlosť ťahania tága myšou hore a dole. Vyššia hodnota = na plné odtiahnutie a silný úder stačí menší pohyb myši, nižšia = jemnejšie dávkovanie sily. Pamätá sa.' ),
		array( '0.7.50', '7. 11. 2026', 'Krieda na špici: po nakriedovaní je spodná polovica špice tága vo farbe kriedy, ktorou si kriedoval. S každým úderom slabne (plná, výrazná, slabá) a po 3 úderoch zmizne. Súper a diváci ju vidia na tvojom tágu.' ),
		array( '0.7.49', '7. 11. 2026', 'Vlastné tágo: pri každej úprave (sila, dĺžka, falše, hmotnosť, priemer špice, tuhosť drievka, vyváženie) je žltý otáznik. Po prejdení myšou vysvetlí, aký vplyv má úprava na mierenie a úder.' ),
		array( '0.7.48', '6. 11. 2026', 'Vzhľad opotrebovanej špice: s opotrebením je špica na tágu nižšia (sploštená), tmavšia, trochu rozpučená do strán a od 30 % má odretý svetlý okraj a tmavé odreté miesta. Mení sa po 5 % (v ruke, na stojanoch aj u súpera), nová špica vyzerá znova ako nová.' ),
		array( '0.7.47', '6. 11. 2026', 'Nepresnosť opotrebovanej špice: od 80 % opotrebenia biela náhodne uhne od smeru mierenia, do 95 % najviac o 0,6°, potom prudko až o 2,5° pri 100 % (tágo štrká celkom krivo). Silnejší úder je nepresnejší, mäkká špica presnejšia, tvrdá menej, menšia špica menej presná. Hodnota nepresnosti je pri špici na stojane F2.' ),
		array( '0.7.46', '6. 11. 2026', 'Stojan F2: v paneli vpravo dole zoznam tág 1 až 10 s výhodami (zelene) a nedostatkami (červeno), šablóna vybraného tága je zvýraznená.' ),
		array( '0.7.45', '6. 11. 2026', 'Vlastné tágo: rozpočet úprav (súčet sily, dĺžky, falší, hmotnosti, priemeru špice a tuhosti najviac 0 %, čo pridáš, inde sa ubere, ostatné posuvníky sa samé znížia). Nové úpravy: hmotnosť (510 až 600 g), priemer špice (9 až 10,5 mm), tuhosť drievka (odklon bielej pri bočnej falši, nová fyzika pre všetky tágá) a vyváženie mimo rozpočtu. Server rozpočet overuje.' ),
		array( '0.7.44', '6. 11. 2026', 'Farba špice je vidno aj na tágach na nástennom stojane v herni (hneď po výbere farby aj po načítaní hry).' ),
		array( '0.7.43', '6. 11. 2026', 'Farba špice: na stojane F2 v sekcii Špica sa dá vybrať farba špice (modrá predvolená, červená, zelená, čierna, oranžová, fialová). Ukladá sa do databázy pri tágu, ostáva aj po výmene špice a súper ju vidí na tvojom tágu.' ),
		array( '0.7.42', '6. 11. 2026', 'Stojan F2, sekcia Špica: malým písmom vysvetlenie, ako špice fungujú (mäkká a tvrdá, slabnutie falší od 70 %, šmyk nad 90 %, upozornenie, asi 1000 úderov).' ),
		array( '0.7.41', '6. 11. 2026', 'Špice tág (v databáze): každé tágo má nasadenú špicu (mäkká, stredná, tvrdá), počíta sa počet úderov a opotrebenie (asi 1000 úderov; mäkká sa pri silných úderoch ničí rýchlejšie, tvrdá silné údery znáša). Opotrebovaná špica slabšie drží falše a nad 90 % sa tágo môže šmyknúť. Na stojane F2 sa dá špica vymeniť za novú a vybrať jej druh; údery starej sa pripočítajú k celkovému počtu úderov a k počtu vymenených špíc.' ),
		array( '0.7.40', '6. 11. 2026', 'Stopy kriedy na súkne: po každom údere ostane pod bielou jemná škvrna vo farbe kriedy hráča (súpera aj sledovaného hráča v jeho farbe), nový frame ich zmaže. Kreslí sa jedným ťahom pre všetky stopy, hra nezasekáva. Kancelária: pri výbere tág do ligy (F2) aj výber jednej kriedy do zápasu.' ),
		array( '0.7.39', '6. 11. 2026', 'Herňa F2: vľavo panel Kriedy s deviatimi kriedami z poličky, každá s vlastnou farbou kriedy aj obalu. Klik na kriedu ju vyberie a kamera sa na ňu priblíži na poličke. Vybratá krieda sa používa pri kriedovaní (F3) a v kresle na štadióne, jej farbu vidí súper aj diváci.' ),
		array( '0.7.38', '6. 11. 2026', 'Herňa: nad stojanom s tágami pribudla polička s modrými kriedami v papierových obaloch. Pohľad F2 je oddialený a širší, vidno celý stojan aj poličku s kriedami.' ),
		array( '0.7.37', '6. 11. 2026', 'Štadión, kreslo F7: F3 nakriedi tágo na ďalší ťah. Pred kreslom sa zdvihne tágo v ruke, krieda sa pošúcha o špičku a po asi 3 sekundách má tágo kriedu. Kriedovanie sa synchronizuje cez internet, vidí ho súper aj diváci.' ),
		array( '0.7.36', '6. 11. 2026', 'Štadión F2: oddialenejší a širší pohľad na stojan, vidno celé tágá od rukovätí po hroty.' ),
		array( '0.7.35', '6. 11. 2026', 'Štadión F2: decentnejšie podsvietenie stojana. Namiesto bielej svetelnej škvrny v strede ho osvetľuje široký mäkký reflektor zhora (vybraté zo štyroch variantov), tágá sú rovnomerne osvetlené.' ),
		array( '0.7.34', '6. 11. 2026', 'Ligový zápas, kreslo F7: keď prídeš na rad, kamera sa prepne k stolu a pípne zvuk na upozornenie. Keď tvoj ťah skončí (súper je na rade), znova si sadneš do kresla s rovnakým pohľadom a priblížením ako predtým, tiež s pípnutím.' ),
		array( '0.7.33', '6. 11. 2026', 'Štadión F2: stojan s tágami sa pri výbere výrazne rozsvieti (LED lišty hore a dole, bodové svetlo spredu na tágá a jemné svetlo na zadnej doske). Podsvietenie sa synchronizuje cez internet, vidia ho súper aj diváci.' ),
		array( '0.7.32', '6. 11. 2026', 'Rozhodca po každom presune postojí na novom mieste aspoň 8 sekúnd, aby sa nepresúval príliš často. Skôr odíde len vtedy, keď by zavadzal tágu. Pri mierenej guli ostáva 10 sekúnd od príchodu.' ),
		array( '0.7.31', '6. 11. 2026', 'Rozhodca sa vyhýba dlhej strane, kde sedia skutoční diváci: nechodí tadiaľ ani tam nezastane, radšej obíde stôl cez kratšie strany. Keď musí, ide stranou s menej skutočnými divákmi. Má to prednosť pri výbere trasy aj miesta pri mierenej guli.' ),
		array( '0.7.30', '6. 11. 2026', 'Štadión F1: namiesto papiera pekný blok so špirálou, linajkami a perom, podrobnejší (klávesy, ovládanie myšou, čas na úder). Vľavo panel so stručnými pravidlami snookeru, vpravo panel s pravidlami počítania bodov ligy.' ),
		array( '0.7.29', '6. 11. 2026', 'Rozhodca: k mierenej guli sa vyberie až po 2,5 sekundy mierenia na tú istú guľu a pri nej ostane aspoň 10 sekúnd, aj keď sa mierenie zmení; skôr odíde len vtedy, keď by zavadzal tágu.' ),
		array( '0.7.28', '6. 11. 2026', 'Štadión: rozhodca pomaly kráča ku guli, na ktorú hráč mieri bielou (zvyčajne červená), na najbližšie miesto okolo stola, kde nezavadzia tágu. Keď sa na guľu nemieri, presúva sa na stanovištia ako doteraz.' ),
		array( '0.7.27', '6. 11. 2026', 'Liga: čas na ťah sa nastavuje pri sezóne ligy (administrácia, Sezóna ligy, Nastavenia sezóny, 15 až 120 sekúnd) a teraz je 45 sekúnd namiesto 30. Platí hneď aj pre rozohrané zápasy sezóny, nová sezóna ho preberá. Časomiera hráča, divákov, obrazovka štadióna aj návod na stolíku idú podľa neho.' ),
		array( '0.7.26', '6. 11. 2026', 'Biela v ruke (začiatok frame aj po spadnutí bielej) sa kladie z pohľadu za tágom, nie zhora: klik zachytí myš, pohybom myši sa biela posúva v D a ľavé tlačidlo ju položí. Hra o skóre (Hrať): Nové rozostavenie je dostupné, začne nový frame s časom a bodmi od nuly a gule sa postavia s trojuholníkom (trojuholník sa ukáže aj pri opakovanom stlačení).' ),
		array( '0.7.25', '6. 11. 2026', 'Prehrávač partie. Kancelária F7, detail zápasu: gombík Prehrať partiu na notebooku prehrá všetky údery zhora na obrazovke notebooku (rovnaká fyzika ako v hre, na konci úderu presný uložený stav stola, skóre, hráč na rade, smer nasledujúceho úderu, správa rozhodcu). Notebook má skutočnú klávesnicu so zvýraznenými šípkami: vľavo predchádzajúci, vpravo ďalší úder, medzerník prehrávanie, Home a End, R rýchlosť. Administrácia: nová záložka Partie s tabuľkou partií cez internet a prehrávačom (presunutá zo stránky Hra).' ),
		array( '0.7.24', '6. 11. 2026', 'Stôl má turnajovú výšku (o 4,5 cm nižší voči podlahe herne, kancelárie aj štadióna). Štadión: nová podlaha vnútri mantinelov, čierna lesklá s tmavosivým kobercom pod stolom a svietiacim modrým LED pásom. Liga: aj výhra s 0 nahratými bodmi (napríklad súperovi vypršal čas) dá aspoň symbolický +1; partia #30 dopísaná spätne (Rugent +1, Pet Mat -1). Nádstavce ostávajú v lige povolené.' ),
		array( '0.7.23', '6. 11. 2026', 'Ligy podľa podielu hráčov, kým ich je najviac 70: 1. liga horných 10 %, 2. liga ďalších 20 %, 3. liga ďalších 30 %, 4. liga zvyšok (v každej aspoň jeden hráč). Pri 7 hráčoch: 1. liga 1 hráč, 2. liga 1, 3. liga 2, 4. liga 3. Výhra nad hráčom z vyššej ligy sa tak ráta 1,5-krát aj pri malom počte hráčov. Nad 70 hráčov platia pevné hranice.' ),
		array( '0.7.22', '6. 11. 2026', 'Kancelária F4 (výsledky sezóny ligy): vpravo panel s pravidlami, ako sa počítajú body (štart, výhra, vzdanie, silnejší súper, spodok, symbolická výhra, ligy, sezóna), výrazným väčším písmom.' ),
		array( '0.7.21', '6. 11. 2026', 'Liga: poistka proti dvojitému započítaniu bodov, keď koniec ligovej partie príde naraz viacerými cestami (koniec framu, čas, odchod hráča). Body sa pripočítajú vždy len raz.' ),
		array( '0.7.20', '6. 11. 2026', 'Herňa: nové obrazy na prednej stene, vľavo úplné zatmenie Slnka, vpravo zatmenie Mesiaca (krvavý Mesiac). S podržaným Ctrl sa dajú kliknúť a priblížiť, späť Enter, Esc alebo pravé tlačidlo myši.' ),
		array( '0.7.19', '6. 11. 2026', 'Liga: symbolická výhra. Keď má porazený 0 alebo menej bodov, víťaz dostane +1 a porazený stratí 1 bod (môže ísť do mínusu). Porazený s kladnými bodmi klesne ako doteraz najviac na 0.' ),
		array( '0.7.18', '6. 11. 2026', 'Trojuholník na gule je čierny plastový so zaoblenými rohmi a nízkym lemom (visí pod stolom). Pri každom novom rozostavení (nový frame, nová partia, F3 Nové postavenie v tréningu) sa objaví okolo červených, chvíľu stojí a potom sa vznesie hore a zmizne.' ),
		array( '0.7.17', '6. 11. 2026', 'Obrazovky nad stolom: raz za minútu ukážu na 5 sekúnd reklamu (striedavo HEDLAJNER a MY SNOOKER) a potom na 3 sekundy skóre zápasu. Všetci to vidia naraz.' ),
		array( '0.7.16', '6. 11. 2026', 'Štadión: nad stolom je už len jedno svietidlo. Svietidlo s obrazovkami visí nižšie, vo výške pôvodných lámp, a nahrádza ich zelené tienidlá; svetlo na stôl ostáva rovnaké. V pohľadoch zhora (výber sedadla, Tab) sa svietidlo nekreslí, aby nezakrylo stôl. Ukážka od diváka: F6 zmena sedadla funguje.' ),
		array( '0.7.15', '6. 11. 2026', 'Svietidlo s obrazovkami: obrazovka na strane k tribúne s dvoma divákmi mala zlý uhol a nesedela v ráme, teraz obe presne kopírujú šikmé steny. Ukážka od diváka (admin): F6 zmena sedadla funguje (výber zhora, klik na stoličku).' ),
		array( '0.7.14', '6. 11. 2026', 'Štadión: obrazovky sú teraz súčasťou svietidla nad stolom. Moderný kužeľ (dole užší, hore širší) visí nad stolom, na oboch šikmých stranách má obrazovku otočenú k tribúne a dole svetelný panel. Obrazovky ukazujú pohľad hráča na rade so širším záberom (inak krúžiacu kameru), divák ich zapne alebo vypne F9 alebo v telefóne F1, zmena platí pre všetkých.' ),
		array( '0.7.13', '6. 11. 2026', 'Štadión: LCD obrazovky sú dočasne odstránené (prerobia sa na iné miesto) a horný rad sedadiel je späť. Nový otočný zelený reflektor: divák ho zapne alebo zhasne klávesom F12 (alebo v telefóne F1), úzky lúč pomaly krúži po hale a tribúnach, stôl obchádza. Vidia ho všetci na rovnakom mieste.' ),
		array( '0.7.12', '6. 11. 2026', 'Koniec ligového zápasu: vždy len jedna pevná kamera z rohu štadióna (stôl, tribúna a tabuľa s víťazom) pre hráčov aj divákov. Medzerník ani iné pohľady sa vtedy nepoužívajú, Esc otvorí menu, M mapu. Okno pohľadu hráča a malý stôl sú vtedy skryté.' ),
		array( '0.7.11', '6. 11. 2026', 'Admin: v mape miestností pri štadióne pribudla Ukážka od diváka (sedíš na tribúne, fungujú F1 telefón, F7 konfety, F8, F9 LCD a Tab, Esc ukážku ukončí). LCD obrazovky: keď nie je koho ukázať, kamera pomaly krúži okolo stola.' ),
		array( '0.7.10', '6. 11. 2026', 'Administrácia, Partie cez internet: nový stĺpec Body ligy (koľko bodov získal víťaz a koľko stratil porazený). Ligová partia, v ktorej porazený nemal žiadne body, sa zapíše ako +0 a nie ako +1.' ),
		array( '0.7.9', '6. 11. 2026', 'Rozhodca stojí pri kratších stranách stola, aby nezavadzal divákom na tribúnach. Na dlhú stranu pred divákov ide len vtedy, keď by pri oboch koncoch zavadzal tágu.' ),
		array( '0.7.8', '6. 11. 2026', 'Štadión: horný rad sedadiel na dlhých tribúnach je odobratý, nezasahuje do LCD obrazovky. Tribúna má 6 radov (300 miest pre divákov).' ),
		array( '0.7.7', '6. 11. 2026', 'Štadión: mantinel s nápisom LIGA ukazuje číslo ligy zápasu (napríklad 1. LIGA), vidia to hráči aj diváci. Liga zápasu je lepšia z líg oboch hráčov.' ),
		array( '0.7.6', '6. 11. 2026', 'Štadión: veľké moderné LCD obrazovky nad oboma dlhými tribúnami. Ukazujú pohľad hráča na rade so širším zorným uhlom, všetci (hráči aj diváci) vidia to isté. Ktorýkoľvek divák ich zapne alebo vypne klávesom F9 alebo v telefóne F1, zmena platí pre všetkých. Nový zápas začína so zapnutými.' ),
		array( '0.7.5', '6. 11. 2026', 'Divák: F8 pohľad hráča vpravo hore (presne to, čo vidí hráč na rade, plynulo 10-krát za sekundu), pod ním malý stôl zhora (Tab). Obe okná sú predvolene zapnuté a hra si pamätá, ktoré si vypol.' ),
		array( '0.7.4', '6. 11. 2026', 'Divák: kláves Tab zapne alebo vypne malý stôl zhora vpravo hore (vidno rozostavenie gúľ a tágo hráča). Hra si nastavenie pamätá.' ),
		array( '0.7.3', '6. 11. 2026', 'Tágo v online partii: súper a diváci vidia na stole tágo, ktoré má hráč na rade naozaj v ruke (aj vlastné upravené tágo). Doteraz každý videl pri každom ťahu svoje vlastné tágo.' ),
		array( '0.7.2', '6. 11. 2026', 'Prezývka z ligy všade: kto má v lige nastavenú prezývku, ostatní ho pod ňou vidia v pozvánkach, zápasoch, na obrazovke a menovkách na štadióne, v tabuľkách, histórii, sledovaní a na mape hráčov. Po uložení prezývky v kancelárii platí hneď. Správa hry vidí meno účtu aj prezývku.' ),
		array( '0.7.1', '6. 11. 2026', 'Jamky podľa miestnosti: na štadióne tesné turnajové (najmenší výrez, tenká svetlá obruba), pri Hrať klasické čierne (čierna kožená obruba a výstelka), v tréningu so širokou svetlou obrubou. Ústie jamiek a fyzika sú všade rovnaké, mení sa len vzhľad.' ),
		array( '0.7.0', '6. 11. 2026', 'Koniec ligového zápasu na štadióne: hráči aj diváci ostanú na štadióne, veľká obrazovka ukáže víťaza (skóre, najvyššia séria, body ligy, výhry v sezóne), zo stropu stále padajú konfety a dvaja diváci ich chvíľu púšťajú; Späť do herne v menu. Divák: F1 telefón s pomocníkom, F7 konfety zo svojho miesta (3-krát za zápas, 15 sekúnd), vidia ich obaja hráči aj ostatní diváci. Admin: Mapa miestností, Štadión, Ukážka konca zápasu.' ),
		array( '0.6.99', '6. 11. 2026', 'Rozhodca má tvár: oči s dúhovkou, obočie, okrúhle okuliare, nos, ústa, vlasy len hore a vzadu. Oprava: tyč krížika a pavúka pri mantineli už neprechádza cez mantinel a rám, stúpa strmšie ponad stôl.' ),
		array( '0.6.98', '6. 11. 2026', 'Jamky ako na turnajových stoloch (na všetkých stoloch): užšie ústie (rohové asi 81 mm, stredné asi 96 mm, aj vo fyzike), svetlá kožená obruba a výstelka jamky, biela sieťka košíka.' ),
		array( '0.6.97', '6. 11. 2026', 'Voľná kamera na štadióne je uzavretá v priestore pri stole po mantinely s reklamami (po divákov), najviac 3,2 m nad podlahu. Admin v prehliadke ostáva bez hraníc.' ),
		array( '0.6.96', '6. 11. 2026', 'Rozhodca chodí: stojí na jednom z 8 stanovíšť okolo stola, a keď by zavadzal tágu (pás za bielou, miesto hráča a kamery), obíde stôl na najbližšie voľné miesto (asi 1 m/s, nohy pri chôdzi kráčajú). Kým sa gule hýbu, stojí. Pohyb vidia rovnako obaja hráči aj diváci (počíta sa z mierenia).' ),
		array( '0.6.95', '6. 11. 2026', 'Jamky: mantinely končia presne na okraji výrezu jamky (už netrčia do jamky), okolo jamky viac dreva a užší otvor v súkne.' ),
		array( '0.6.94', '6. 11. 2026', 'Štadión: rozhodca stojí bokom pri dlhej strane stola (biela košeľa, čierna vesta s gombíkmi, motýlik, biele rukavice, ruky zopäté) a hlavou sleduje bielu guľu.' ),
		array( '0.6.93', '6. 11. 2026', 'Štadión: pri kresle každého hráča okrúhly stolík s pohárom vody a menovkou s menom hráča (admin má pod menom ADMIN). Na stolíku rozhodcu ostal jeden pohár vody.' ),
		array( '0.6.92', '6. 11. 2026', 'Výkon: kreslí sa len miestnosť, v ktorej hráč je. Kancelária už nevisí za herňou ani na štadióne, v kancelárii sa nekreslí herňa ani stôl; skryté miestnosti nemajú ani svetlá. Admin v prehliadke vidí všetko.' ),
		array( '0.6.91', '6. 11. 2026', 'Mapa miestností (M) funguje aj v kancelárii.' ),
		array( '0.6.90', '6. 11. 2026', 'Mapa miestností (kláves M alebo tlačidlo v menu): pôdorys s herňou, kanceláriou a štadiónom, klik na miestnosť ukáže popis a tlačidlo Vstúpiť. Štadión je pre hráčov zamknutý (hrá sa tam len liga, otvorí sa pri nájdenom zápase), admin tam môže trénovať a má aj Prehliadku voľnou kamerou (presunutá z Nastavení). Miestnosti sú v jednom zozname, ďalšie sa pridajú ľahko.' ),
		array( '0.6.89', '6. 11. 2026', 'Oprava: tmavé „praskliny“ na koncoch mantinelov pri jamkách (prierez gumy sa v zaoblení prekladal cez seba).' ),
		array( '0.6.88', '6. 11. 2026', 'Online: súper a diváci vidia nádstavec (krížik, pavúk, vysoký pavúk) aj kriedovanie tága druhého hráča, posiela sa spolu s mierením.' ),
		array( '0.6.87', '6. 11. 2026', 'Oprava: po zatvorení ponuky F3 (F3 alebo Esc) a po nakriedovaní sa myš znova zachytí v hre.' ),
		array( '0.6.86', '6. 11. 2026', 'Oprava: tágo už neprechádza cez krížik ani pavúka, leží presne v drážke (výška nádstavca sa riadi skutočnou polohou tága, aj pri údere vyššie alebo nižšie na bielu).' ),
		array( '0.6.85', '6. 11. 2026', 'Krížik pri mantineli sa kladie na rám čo najďalej k vonkajšiemu okraju stola, tágo má menší sklon.' ),
		array( '0.6.84', '6. 11. 2026', 'Tréning si pamätá rozloženie gúľ a štatistiku aj po obnovení stránky (F5) a po návrate z hry o skóre; ukladá sa po každom údere a po Späť, Biela do ruky, Hotovo a Nové rozostavenie.' ),
		array( '0.6.83', '6. 11. 2026', 'Krížik sa dá použiť aj pri mantineli: ak za bielou nie je miesto na súkne, položí sa na drevený rám za mantinelom (tágo ide strmšie). Pavúky pri mantineli ostávajú zakázané.' ),
		array( '0.6.82', '6. 11. 2026', 'Oprava: trojuholník pod stolom už netrčí do stola (visí nižšie pod rámom).' ),
		array( '0.6.81', '6. 11. 2026', 'Nádstavce na teleskopickej tyči s drevenou rukoväťou: krížik (nízky, zmestí sa aj bližšie k mantinelu), pavúk (mosadzný oblúk s korunkou a žliabkami) a vysoký pavúk (U). Výber v ponuke F3 (2 až 4, 5 nové postavenie gúľ), každý drží tágo v inom sklone. Oprava: F3 už neotvorí hlavné menu.' ),
		array( '0.6.80', '6. 11. 2026', 'Pavúk ako skutočná pomôcka: dlhá drevená palica a na jej konci mosadzná hlava v tvare oblúka s dvoma nohami a tromi drážkami, palica ide dozadu k ruke ponad mantinel. Pod stolom visí vodorovne pozdĺž čela skrine.' ),
		array( '0.6.79', '6. 11. 2026', 'Zlatý krúžok pod vybratým tágom pri stojane sa ukazuje len v pohľade F2.' ),
		array( '0.6.78', '6. 11. 2026', 'Pavúk (spider) a ponuka F3: F3 otvorí ponuku Nakriedovať, Pavúk a Nové postavenie gúľ. Pavúk sa položí sám za bielu na najbližšie voľné miesto, tágo na ňom leží vždy v rovnakom sklone, platí na jeden úder. Pri mantineli nefunguje. Pod stolom visí pavúk (strana baulku) a na druhom konci trojuholník, oba sa dajú vziať Ctrl a klikom. Pri mantineli sa úder automaticky posunie vyššie na bielu (tágo sa menej zdvíha), dá sa doladiť na guli Miesto úderu, sklon tága a kamera sa prispôsobia.' ),
		array( '0.6.77', '6. 11. 2026', 'Oprava: návrat z pohľadu na predmet pravým tlačidlom pri držanom Ctrl nechá myš voľnú (kurzor ostane, predmety sa ďalej rozsvecujú).' ),
		array( '0.6.76', '6. 11. 2026', 'Vypínač na stene vľavo od dverí herne: s Ctrl a kliknutím zhasne alebo rozsvieti nástenné lampy, potom svieti len nad stolom. Pamätá sa.' ),
		array( '0.6.75', '6. 11. 2026', 'Admin: v Nastaveniach Prehliadka (Herňa, Štadión, Kancelária), voľná kamera bez hraníc miestností.' ),
		array( '0.6.74', '6. 11. 2026', 'Nová podlaha herne: tmavý parket s bordovým kobercom so zlatým lemom pod stolom, nakreslená ako celok bez viditeľných švov textúry.' ),
		array( '0.6.73', '6. 11. 2026', 'Rádio si pamätá, či hralo: po obnovení stránky (F5) sa zapne samo pri prvom kliknutí alebo klávese (prehliadač zvuk skôr nedovolí).' ),
		array( '0.6.72', '6. 11. 2026', 'Jamky bez čiernych dier: cez otvor v súkne vidieť do košíka. Pri držanom Ctrl sa vľavo hore výrazne zobrazí FPS (zelené, pod 50 žlté, pod 30 červené).' ),
		array( '0.6.71', '6. 11. 2026', 'Nohy stola posunuté pod zapustenú skriňu (netrčia von).' ),
		array( '0.6.70', '6. 11. 2026', 'Ctrl a klik: rádio na komode aj mixpult otvoria to isté (F9, rádio).' ),
		array( '0.6.69', '6. 11. 2026', 'Jamky s košíkmi: pod každou jamkou visí sieťka a spadnuté gule (väčšinou červené) v nej ostávajú vidieť, kým sa nevrátia na stôl. Skriňa stola je pod rámom zapustená, aby boli košíky vidieť.' ),
		array( '0.6.68', '6. 11. 2026', 'Nastavenia: Vzhľad stola. Podrobný (predvolený): súkno s leskom látky, jemnou tkaninou, smerom vlasu a tenšími čiarami, mahagónový rám pod lakom, perleťové značky. Jednoduchý: pôvodný vzhľad pre slabšie zariadenia.' ),
		array( '0.6.67', '6. 11. 2026', 'Voľná kamera: ruky s tágom sa zapínajú a vypínajú klávesom F3, predvolene sú vypnuté.' ),
		array( '0.6.66', '6. 11. 2026', 'Pravé tlačidlo: samotné stlačenie pohľad nezmení, k mierenej guli sa pohľad otáča až s pohybom myši; koliesko pri držanom pravom tlačidle platí len počas držania.' ),
		array( '0.6.65', '6. 11. 2026', 'Voľná kamera: menšie ruky, v pravej ruke vybraté tágo; ku stene herne sa dá ísť len na dĺžku rúk.' ),
		array( '0.6.64', '6. 11. 2026', 'Pohľad pravým tlačidlom: myš hore približuje ku guli po priamke pohľadu (uhol sa nemení, obraz už neťahá dole) a kamera pritom mierne stúpa.' ),
		array( '0.6.63', '6. 11. 2026', 'Ruky pri tágu odstránené; ruky ostávajú len vo voľnej kamere a sú menšie.' ),
		array( '0.6.62', '6. 11. 2026', 'Ruky hráča: vo voľnej kamere ruky pred kamerou namiesto tága, pri mierení ľavá ruka ako most na súkne a pravá na konci tága. Oprava: priblíženie kolieskom pri pravom tlačidle už neberie stúpanie pohľadu (mení len vzdialenosť od gule, výška ostáva).' ),
		array( '0.6.61', '6. 11. 2026', 'Priblíženie kolieskom je zvlášť za tágom a zvlášť pri držanom pravom tlačidle (pohľad na mierenú guľu); obe sa pamätajú aj po obnovení hry.' ),
		array( '0.6.60', '6. 11. 2026', 'Pohľad pravým tlačidlom za tágom: myš hore priblíži pohľad ku mierenej guli (kamera pritom mierne stúpa), dole oddiali, doľava a doprava krúži okolo nej.' ),
		array( '0.6.58', '6. 11. 2026', 'Pohľad pravým tlačidlom za tágom: kamera krúži okolo gule, na ktorú sa mieri, v rovnakej vzdialenosti (predtým sa pri otáčaní dookola po špirále vzďaľovala).' ),
		array( '0.6.57', '6. 11. 2026', 'Pravé tlačidlo myši v pohľade na predmet (nástenka, stojan, skóre, kreslo a ďalšie) vráti pohľad za tágo.' ),
		array( '0.6.56', '6. 11. 2026', 'Ctrl drž: dole sa zobrazia tlačidlá (Späť, Biela do ruky, Nové rozostavenie), inak sú skryté, a šúpatko Otáčanie myšou (rýchlosť otáčania kamery a mierenia, pamätá sa). Vo voľnej kamere Ctrl a pravé tlačidlo zruší priblíženie.' ),
		array( '0.6.55', '6. 11. 2026', 'Rozsvietenie a klik na predmety s Ctrl funguje aj za tágom počas hry, nielen vo voľnej kamere.' ),
		array( '0.6.54', '6. 11. 2026', 'Voľná kamera: s držaným Ctrl sa predmet pod kurzorom jemne rozsvieti a klik urobí to isté ako jeho kláves (nástenka, stojan, skóre, kreslo, poháre, bar, nástenka ligy; na štadióne návod, stojan, obrazovka, kreslo).' ),
		array( '0.6.53', '6. 11. 2026', 'Voľná kamera: Esc pohľad neprepína, len uvoľní myš a otvorí menu (späť za tágo je medzerník). Koliesko približuje a odďaľuje, pravé tlačidlo myši hore, ľavé dole; s Ctrl fungujú tlačidlá normálne. Plán: mini náhľad stola na Tab vo voľnom pohľade, ELO len z ligových zápasov.' ),
		array( '0.6.51', '6. 11. 2026', 'Plán vývoja: ochrana proti podvádzaniu sa robí až pred dokončením hry.' ),
		array( '0.6.50', '6. 11. 2026', 'Role admin a správca hry: administrácia My Snooker, Hráči (zoznam hráčov, nastavenie roly správca hry), v hre tlačidlo Správa hry (bežiace zápasy, herne, hráči online, neviditeľné sledovanie, zmena prezývky; admin aj ukončenie alebo zrušenie zápasu, zákaz ligy, vynulovanie bodov). Voľná kamera: návrat za tágo je okamžitý, bez preletu; koliesko plynulo posúva kameru hore a dole, držané pravé tlačidlo približuje na predmet, na ktorý sa pozeráš.' ),
		array( '0.6.49', '6. 11. 2026', 'Voľná kamera si pamätá polohu a smer pohľadu (v tej istej miestnosti sa k nim vráti), pohyb je plynulý (rozbeh a dobeh, pohľad bez oneskorenia). Úder klávesom zrušený: udiera sa len myšou (ťahaním tága alebo ukazovateľom sily), Enter bude neskôr chat.' ),
		array( '0.6.48', '6. 11. 2026', 'Voľná kamera: medzerník prepína voľný pohľad a pohľad za tágo aj počas hry (herňa a štadión). Myš rozhliadanie, šípky alebo W A S D posun, Q a E dole a hore, Shift rýchlejšie, koliesko priblíženie, Ctrl zastaví kameru, Esc späť; keď v zápase prídeš na rad, kamera sa vráti za tágo. Úder klávesom je teraz na Entere (drž a pusť). Administrácia: v menu My Snooker odkaz Dokumentácia (návod v My Help).' ),
		array( '0.6.47', '6. 11. 2026', 'Plán vývoja: ELO sila hráča (štart 1350), klik na predmety v scéne vo voľnom pohľade, upresnená voľná kamera (medzerník prepína, Ctrl zastaví kameru).' ),
		array( '0.6.46', '6. 11. 2026', 'Plán vývoja: role admin a správca hry schválené (zoznam hráčov s nastavením roly, panel Správa hry, odkaz Dokumentácia), voľná kamera schválená, TURN server odložený.' ),
		array( '0.6.45', '6. 11. 2026', 'Plán vývoja: doplnená ochrana proti podvádzaniu (súper ako rozhodca, kontrola bodov na serveri, overenie skóre v hre o skóre).' ),
		array( '0.6.44', '5. 11. 2026', 'Priame spojenie hráčov (WebRTC): zakolísané spojenie sa opraví bez nového nadväzovania (ICE restart), chyba pri odosielaní signálu sa skúsi znova, zastaraná ponuka nezhodí živé spojenie, kontrolný signál každé 2 s (bez odozvy 6 s spustí opravu, nie keď je hra v pozadí), limit signálov zvlášť pre každé spojenie, menej požiadaviek na server, po návrate z inej karty sa hneď načíta stav partie. Administrácia: nová stránka Diagnostika spojení (výpadky a opravy, príčina, cesta spojenia, sieť, prehliadač, záznam udalostí).' ),
		array( '0.6.43', '5. 11. 2026', 'Plán vývoja: doplnený TURN server pre priame spojenie hráčov (riešiť neskôr).' ),
		array( '0.6.42', '5. 11. 2026', 'Spojenie so súperom: krátky výpadok siete už priame spojenie (WebRTC) hneď neruší, počká sa 15 sekúnd, či sa samo neobnoví (predtým 4 s). V ligovom zápase je pri výpadku správny text: partia pokračuje, stav stola sa berie zo servera, súper bez spojenia prehrá po 2 minútach.' ),
		array( '0.6.41', '5. 11. 2026', 'Oprava rozdielnych pozícií gúľ u hráčov: fyzika počíta vždy rovnaké celé kroky bez ohľadu na rýchlosť počítača a počet snímok za sekundu (predtým mohli gule u súpera skončiť inde). Keď vypadne priame spojenie so súperom a jeho výsledok úderu nepríde, hra pri najbližšom pingu zistí novší úder na serveri a načíta uložený stav stola.' ),
		array( '0.6.40', '5. 11. 2026', 'Štadión: hráči sedia v čalúnených kreslách (namiesto stoličiek). Nastavenia: Kamera, keď hrá súper (ligový štadión). Sledovať súpera (predvolené, ako doteraz), Pohľad zhora alebo Z kresla (F7): keď súper príde na rad, kamera sa prepne a ostane tak počas celého jeho ťahu; keď prídeš na rad, vráti sa za tágo.' ),
		array( '0.6.39', '5. 11. 2026', 'Nastavenia: Kamera po údere. Sledovať bielu (predvolené, ako doteraz) alebo Pohľad zhora na stôl: po mojom aj súperovom údere kamera ukáže celý stôl zhora a keď gule zastanú, vráti sa za tágo do smeru mierenia pred úderom.' ),
		array( '0.6.38', '5. 11. 2026', 'Oprava časomiery: po údere (vlastnom aj súperovom) sa čas a odpočet hneď skryjú, aj kým sa súperov úder prehráva a čaká sa na výsledok. Znova beží až pri ďalšom ťahu. Rovnako u divákov.' ),
		array( '0.6.37', '5. 11. 2026', 'Liga: časomiera. Hráč na rade má na úder 30 sekúnd (hore ukazovateľ času, od 10 s žltý, posledných 5 s veľký odpočet s tiknutím, pri nule Čas!). Kto nestihne, má faul za čas: súper dostane 4 body alebo hodnotu gule na rade a je na rade. Keď má hráč hru zatvorenú, faul po 3 sekundách zapíše server na podnet súpera. Čas vidia aj diváci a je na veľkej obrazovke štadióna.' ),
		array( '0.6.36', '5. 11. 2026', 'Oprava: pri naťahovaní tága ľavým tlačidlom myši (najmä pri bielej pri mantineli, keď je tágo zdvihnuté) sa už nemení uhol tága ani pohľad kamery. Sklon sa určí z polohy tága bez odtiahnutia a tágo sa pri naťahovaní len posúva po svojej osi.' ),
		array( '0.6.35', '5. 11. 2026', 'Nastavenia: Detail dotyku pri mierení má štyri možnosti: v strede dole, vľavo dole (vedľa Miesta úderu), vpravo dole (vedľa ukazovateľa sily) alebo nezobrazovať. Zmena platí hneď.' ),
		array( '0.6.34', '5. 11. 2026', 'Pravidlá: voľná guľa. Keď po faule súper nevidí priamo oba okraje žiadnej gule na rade, dostane voľnú guľu (na lište: voľná guľa alebo guľa na rade). Ľubovoľná farba platí ako guľa na rade, potopená sa vráti na spot. Platí v partii s priateľom aj v lige, v hre o skóre nie.' ),
		array( '0.6.33', '5. 11. 2026', 'Administrácia: nová stránka My Snooker, Sezóna ligy. Prehľad aktuálnej sezóny (začiatok, koniec, hráči, zápasy, prvé miesto), posun dátumu konca a názvu, tlačidlo Ukončiť sezónu a začať novú s potvrdením (riadne s majstrom, alebo ako testovacia bez majstra a bez poradia; dĺžka novej sezóny rok, 6, 3 alebo 1 mesiac) a zoznam minulých sezón.' ),
		array( '0.6.32', '5. 11. 2026', 'Plán vývoja: hra proti počítaču nebude (etapa vypustená, ostatné etapy prečíslované).' ),
		array( '0.6.31', '5. 11. 2026', 'Plán vývoja: viac hráčov na jednom zariadení zatiaľ nie je podporované (2. etapa sa volá Pravidlá snookeru). Prehľad režimov v administrácii je aktuálny.' ),
		array( '0.6.30', '5. 11. 2026', 'Plán vývoja aktualizovaný: hotové etapy 3D stôl a tréning, 2 hráči cez internet a sledovanie, rebríček a história, liga; nová etapa Dokončenie a doladenie. Oprava: záznamy denníka zmien 0.6.17 až 0.6.29 sa omylom zobrazovali v pláne vývoja.' ),
		array( '0.6.29', '5. 11. 2026', 'Oprava: podrobná mapa sveta v kancelárii sa načíta aj v hre na adrese snooker.hedlajner.sk (súbor s hranicami štátov sa berie z tej istej domény).' ),
		array( '0.6.28', '5. 11. 2026', 'Kancelária: nová podrobná mapa sveta s hranicami všetkých štátov (Natural Earth 1:50 mil., verejné vlastníctvo). Krajiny s hráčmi ligy sú zvýraznené, každá má jeden špendlík s počtom hráčov (moja krajina zlatý, ostatné strieborné), mená sa už neprekrývajú. Ctrl a klik na špendlík ukáže hráčov krajiny s ligou, miestom a bodmi.' ),
		array( '0.6.27', '5. 11. 2026', 'Vyhľadávanie ligového zápasu: hore je žltý pásik Vyhľadáva sa ligový zápas s časom a krížikom na zrušenie (v menu aj v hre). Hľadanie beží aj po odchode z kancelárie (tréning, hra o skóre, sledovanie), zruší ho krížik, výzva na partiu alebo zhasnutá lampa. Nájdený zápas treba potvrdiť do 60 sekúnd vo výraznom okne (Prijať alebo Zrušiť, súper sa neukazuje); Zrušiť vypne aj vyhľadávanie. Keď súper nepotvrdí, hľadá sa ďalej.' ),
		array( '0.6.26', '5. 11. 2026', 'Kancelária: F7 priblíži notebook a vpravo otvorí panel Moje zápasy v lige. Všetky ligové zápasy (aj zrušené a prehraté pre výpadok) s dátumom, súperom, skóre, výsledkom a bodmi ligy, súhrn výhier a prehier a najvyšší brejk. Klik na zápas ukáže detail: porovnanie hráčov (body, najvyšší brejk, údery, fauly, trestné body), graf priebehu skóre a priebeh partie (brejky a fauly v poradí).' ),
		array( '0.6.25', '5. 11. 2026', 'Oprava: oblečenie v šatníku pri pohybe kamery neblikalo medzi košeľou a vestou (časti sa prekrývali v rovnakej hĺbke).' ),
		array( '0.6.24', '5. 11. 2026', 'Kancelária: namiesto knižnice s pohármi majstrov stojí pri pravej stene otvorený šatník bez dverí. Na tyči visí oblečenie na zápas (biela košeľa s čiernym motýlikom, tmavá vesta so zlatými gombíkmi, čierne nohavice), dole sú čierne lakované topánky. Zatiaľ je len na pohľad.' ),
		array( '0.6.23', '5. 11. 2026', 'Štadión: F1 ukáže papier s krátkym návodom na klávesy, ktorý leží na stolíku rozhodcu medzi dvoma pohármi s vodou (bez bočného panela). F8, F9 a F10 na štadióne zatiaľ nerobia nič.' ),
		array( '0.6.22', '5. 11. 2026', 'Štadión: pohľad zo stoličky (F7) je bez bočného panela s novinami. Keď hráč sedí na stoličke a príde na rad, pohľad sa sám vráti k stolu za tágo (platí v každej partii).' ),
		array( '0.6.21', '5. 11. 2026', 'Oprava: divák ligového zápasu vidí na veľkej obrazovke štadióna (F4) skutočné skóre partie: mená hráčov, body, kto je na rade, sériu a guľu na rade, nie len nápis Vyzvi hráča z ligy.' ),
		array( '0.6.20', '5. 11. 2026', 'Štadión: každý hráč má svoju stranu. Hráč 1 sedí v rohu pri dlhej strane so svojou stoličkou (F7) a stojanom so svojimi tágami (F2), hráč 2 oproti v druhom rohu so svojou stoličkou a svojimi tágami. Súper aj diváci vidia na stojane tágá hráča, ktoré si vybral do ligy (tágo v ruke na stojane chýba).' ),
		array( '0.6.19', '5. 11. 2026', 'Online divák si pri vstupe vyberie miesto zhora: na štadióne voľnú stoličku na tribúne, v herni miesto na státie pri stene (zelené voľné, sivé obsadené, každé miesto má len jeden divák). Pozerá zo svojho miesta, myšou sa rozhliada a kolieskom približuje. F4 ukáže skóre zblízka ako hráčovi, F6 zmení miesto. Hráči aj ostatní diváci vidia na mieste diváka postavičku s jeho menom, ktorá tlieska pri potopenej guli a chytá sa za hlavu pri faule. Stoličky kulisových divákov sú vždy obsadené. Divák neprepína bodové svetlá (F12).' ),
		array( '0.6.18', '5. 11. 2026', 'Štadión: keď hráč na ťahu zapne alebo zhasne bodové svetlá (F12), rovnako sa zmenia aj súperovi a divákom. Diváci sedia presne na stoličkách.' ),
		array( '0.6.17', '5. 11. 2026', 'Štadión: bodové svetlá reflektorov svietia šikmo na stôl a až po zem. Pred partiou svietia, po prvom údere samy zhasnú, F12 ich zapne alebo vypne, keď si na ťahu. F2 ukáže stojan v rohu arény a vyberá sa len z tág vybratých do ligy (najviac 4, nastavujú sa v kancelárii). Na druhej strane sedia vedľa seba dvaja ďalší diváci. V menu partie je Vzdať partiu hneď pod Pokračovať v partii.' ),
		array( '0.6.16', '5. 11. 2026', 'Štadión: tágá zo stojana v herni už nevisia pred tribúnou. V rohu arény vedľa stoličky hráča je nízky drevený stojan s tágami vybratými do zápasu (tágo v ruke na ňom chýba). F4 na štadióne ukáže skóre na veľkej obrazovke nad tribúnou.' ),
		array( '0.6.15', '5. 11. 2026', 'Štadión: lúče reflektorov svietia zo šošovky až na podlahu vedľa stola a končia svetlou škvrnou. Ligový zápas sa nedá prerušiť (v menu len Vzdať partiu): komu vypadne spojenie na 2 minúty, prehrá ako pri vzdaní, keď vypadne obom, zápas sa zruší bez bodov.' ),
		array( '0.6.14', '5. 11. 2026', 'Kancelária: lampa na stole sa zhasína a rozsvecuje klávesom F12 alebo klikom. Zhasnutá lampa znamená, že hráč nie je online: nevidia ho v zoznamoch, nedá sa vyzvať, jeho otvorené dvere nie sú v Pozerať hru a nedá sa hľadať zápas (prebiehajúce hľadanie sa zruší). Stav lampy si hra pamätá.' ),
		array( '0.6.13', '5. 11. 2026', 'Kancelária: na stole notes s perom ukazuje, koľko hráčov je práve v hre a koľkí čakajú na ligový zápas (obnovuje sa s pingom). Za stolom stojí kancelárska stolička. Vyhľadať zápas (dvere ŠTADIÓN, F9) ani vyzvať hráča z ligy sa nedá bez vybraného tága do zápasu, hra otvorí výber tág.' ),
		array( '0.6.12', '5. 11. 2026', 'Hra je na stránke Nástroje webu ako prvá: My Snooker, 3D snooker s ligou (ikona tága s guľou, My Users 1.4.4).' ),
		array( '0.6.11', '5. 11. 2026', 'Po údere sa kamera neotáča: keď gule zastanú a si na rade, mieriš zo smeru, z ktorého sa kamera práve pozerá na bielu (aj keď si sa počas pohybu otočil myšou), kamera sa len plynulo spustí za tágo. V partii platí aj po súperovom údere, mierenie sa už samo neotáča na najbližšiu guľu.' ),
		array( '0.6.10', '5. 11. 2026', 'E-maily účtu poslané z hry (potvrdenie registrácie, už máš účet, zabudnuté heslo) majú tému snookru: zelené súkno s guľami, zlatý nadpis My Snooker, žlté tlačidlo Potvrdiť účet a hrať a pätička s adresou hry. Text e-mailu ostáva od My Users a WordPressu, e-mail pre správcu webu sa nemení.' ),
		array( '0.6.9', '5. 11. 2026', 'Oprava: Odhlásiť sa v okne Účet nechalo hráča na stránke wp-login.php (adresa odhlásenia mala zakódované &amp; a stratil sa návrat do hry). Teraz odhlási a vráti späť do hry.' ),
		array( '0.6.8', '5. 11. 2026', 'V menu pribudol Účet (nad Nastaveniami): meno, e-mail, člen od, úroveň, liga (sezóna, liga a miesto, body, výhry a prehry), dohraté partie cez internet, hra o skóre (framy, najlepšie skóre, najvyšší brejk) a vlastné tágá; odkazy Môj účet na webe, Môj e-shop a Odhlásiť sa. Tlačidlo Vstúpiť sa volá Pozerať hru.' ),
		array( '0.6.7', '5. 11. 2026', 'Oprava: Cache Enabler posielal neprihláseným návštevníkom na snooker.hedlajner.sk starú uloženú stránku hry (z verzie 0.5.3), preto Prihlásiť sa viedlo na wp-login.php. Stránka hry sa už do cache neukladá a stará kópia sa po novej verzii zmaže sama.' ),
		array( '0.6.6', '5. 11. 2026', 'Okno prihlásenia má vzhľad hry: tmavé okno ako menu, zlatý nadpis My Snooker, zlaté karty a odkazy, žlté tlačidlo Prihlásiť sa. Formulár ostáva ako na stránke Prihlásenie (Google, e-mail a heslo, zapamätať, zabudnuté heslo, registrácia).' ),
		array( '0.6.5', '5. 11. 2026', 'Prihlásenie v okne hry funguje aj na subdoméne snooker.hedlajner.sk: formulár ide na snooker.hedlajner.sk/prihlasenie, kde ho spracuje doplnok My Users (tie isté kontroly a obmedzenie pokusov), prihlásenie platí pre celý web. Google prihlási a vráti späť do hry.' ),
		array( '0.6.4', '5. 11. 2026', 'Oprava: po prihlásení zo subdomény snooker.hedlajner.sk WordPress posielal hráča do wp-admin, lebo adresa hry nebola povolený cieľ presmerovania. Teraz sa vráti späť do hry (aj cez Google). My Users 1.4.2: už prihlásený na stránke Prihlásenie ide späť do hry a prihlásenie sa obnoví aj pre subdoménu.' ),
		array( '0.6.3', '5. 11. 2026', 'Oprava: tlačidlo Prihlásiť sa v menu neprihláseného návštevníka sa roztiahlo cez celú obrazovku a zakrylo hru (rovnaký názov štýlu ako okno prihlásenia). Na subdoméne snooker.hedlajner.sk vedie Prihlásiť sa na stránku Prihlásenie hlavného webu (okno v hre funguje len na adrese hedlajner.sk/my-snooker).' ),
		array( '0.6.2', '5. 11. 2026', 'Prihlásenie a registrácia priamo v hre, v okne v štýle stránky Prihlásenie (Google, e-mail a heslo, zabudnuté heslo), nie cez wp-admin. Formulár ide na stránku Prihlásenie z My Users, chyby sa ukážu v okne a po prihlásení sa hra načíta znova už s účtom.' ),
		array( '0.6.1', '5. 11. 2026', 'Tágo sa pri mierení samo zdvihne nad guľu, ktorá leží za bielou, podobne ako nad mantinel (najviac o 40 stupňov). Je to len vzhľad, úder sa nemení. Po skončení zápasu (aj ligového zo štadióna) sa hráč vráti domov do herne a v menu má vybratý Tréning. Výber tág do ligy v kancelárii (F2) je najviac v dvoch riadkoch, ďalšie tágá sú vpravo (posun kolieskom myši alebo posuvníkom) a moje uložené tágá sú prvé zľava.' ),
		array( '0.6.0', '4. 11. 2026', 'Partia cez internet a sledovanie idú priamo medzi prehliadačmi cez WebRTC: mierenie tága asi 20-krát za sekundu, úder a výsledok hneď, bez čítania servera dookola. Server len sprostredkuje nadviazanie spojenia (nová tabuľka my_snooker_signals) a ukladá partiu a odohrané ťahy. Divák sa spojí s hráčom otvorenej partie alebo s oboma hráčmi ligového zápasu.' ),
		array( '0.5.3', '4. 11. 2026', 'Tágo, s ktorým hráš, nie je pri hre na stojane (je v ruke, jeho miesto je prázdne). Na stojane je len v pohľade F2, keď si prezeráš tágá.' ),
		array( '0.5.2', '4. 11. 2026', 'Neprihlásený návštevník má v menu aj Tréning: zahrá si voľný tréning bez prihlásenia. Hra o skóre, liga, partie s priateľmi a vlastné tágá ostávajú pre prihlásených.' ),
		array( '0.5.1', '4. 11. 2026', 'Moje tágá sú v paneli vpravo pod nastaveniami (Vybrať, Na stojan, Zo stojana). Na stojane je vždy 10 tág: vlastné tágo sa dá dať na stojan namiesto svojej šablóny, aj v 3D s jeho farbami.' ),
		array( '0.5.0', '4. 11. 2026', 'Vlastné tágá: na stojane (F2) je vpravo priehľadný panel so všetkými vlastnosťami vybraného tága. 10 tág hry sú šablóny, z každej si prihlásený hráč vyrobí vlastné tágo (najviac 10): názov a farby dreva a rukoväte voľne, sila, dĺžka a falše o ±10 % od šablóny. Vlastné tágá sú na stojane v skupine Vlastné, dajú sa vybrať aj do ligy (F2 v kancelárii). Nová tabuľka my_snooker_cues.' ),
		array( '0.4.3', '4. 11. 2026', 'Kruh s detailom dotyku má farbu súkna stola (zelená, pri tréningu červená, v lige modrá). Guľa, na ktorú sa mieri, už nesvieti, označuje ju len krúžok na súkne.' ),
		array( '0.4.2', '4. 11. 2026', 'Sledovanie: divák vidí tágo hráča pri mierení (aj v ligovom zápase) a stôl sa zosúladí aj pri zmenách bez úderu (biela do D, krok späť, nové rozostavenie). Divák sa pýta na stav dvakrát za sekundu.' ),
		array( '0.4.1', '4. 11. 2026', 'Oprava: Esc zavrie hlavné menu a to sa už samo znova neotvorí. Myš sa zachytí prvým klikom do hry.' ),
		array( '0.4.0', '4. 11. 2026', 'Vstúpiť v menu: okno Otvorené partie so zoznamom tréningov a hier o skóre s otvorenými dverami (F6) a všetkých prebiehajúcich ligových zápasov. Divák sa len pozerá: vidí každý úder naživo, myšou sa otáča okolo stola, Esc otvorí menu s tlačidlom Prestať sledovať. Dvere herne sú po načítaní zatvorené, partia je súkromná, kým ich hráč neotvorí. Nová tabuľka my_snooker_rooms.' ),
		array( '0.3.13', '4. 11. 2026', 'Esc pri otvorenom hlavnom menu ho zavrie a pokračuje sa v hre. Tágá v kancelárii (F2) sú v dvoch riadkoch po 5. Po návrate od tág, zatvorení vizitky alebo registrácii sa v kancelárii znova dá rozhliadať myšou.' ),
		array( '0.3.12', '4. 11. 2026', 'V strope kancelárie sú dva reproduktory: keď hrá rádio z herne, v kancelárii je počuť z nich (priestorovo). Po návrate do herne hrá znova z reproduktorov v herni.' ),
		array( '0.3.11', '4. 11. 2026', 'F2 v kancelárii len vyberá 4 tágá do ligového zápasu a jedno z nich označí ako predvolené (★, modrý krúžok na stojane). Nastavenia tág z kancelárie zmizli, budú na stojane v domácej herni.' ),
		array( '0.3.10', '4. 11. 2026', 'V kancelárii klik bez Ctrl nerobí nič. S podržaným Ctrl (voľná myš) sa dá kliknúť na vizitku, dvere ŠTADIÓN a ikonky hráčov na mape. Tabuľa líg na klik nereaguje (priblíži ju F4).' ),
		array( '0.3.9', '4. 11. 2026', 'Klik na tabuľu líg v kancelárii ju priblíži (ako F4), okno s tabuľkami sa už neotvára.' ),
		array( '0.3.8', '4. 11. 2026', 'Oprava: v kancelárii znova funguje F5 (obnovenie stránky) a F11 (celá obrazovka).' ),
		array( '0.3.7', '4. 11. 2026', 'Oprava: F6 v kancelárii otvára okno (predtým otváralo dvere herne).' ),
		array( '0.3.6', '4. 11. 2026', 'Za hráčom v kancelárii je vysoké okno s výhľadom na večerné mesto a osvetlený štadión. F6 okno otvorí alebo zatvorí (krídla sa otvoria dovnútra). Mapa hráčov je teraz na F10.' ),
		array( '0.3.5', '4. 11. 2026', 'F2 v kancelárii funguje ako stojan v herni: kamera sa priblíži ku stojanu s tágami, dole sú karty tág (klik tágo zoberie do ligového zápasu alebo odoberie, najviac 4) a pod nimi nastavenia vybraného tága (šípky menia tágo).' ),
		array( '0.3.4', '4. 11. 2026', 'Kancelária bez bočného panela, s drevenou podlahou a drevenými stenami. Vlastné klávesy: F1 nástenka s klávesmi na stene za hráčom, F2 tágá do ligového zápasu, F3 kalendár, F4 tabuľa výsledkov líg, F6 mapa hráčov, F7 notebook Moja liga, F8 vizitka, F9 vyhľadať zápas. Dvere ŠTADIÓN za hráčom vpravo spustia vyhľadávanie ligového zápasu: kto je práve vo fronte, hrá s kýmkoľvek ďalším, a obaja prejdú na štadión.' ),
		array( '0.3.3', '4. 11. 2026', 'Pri tréningu (aj spoločnom tréningu s priateľom) ukazujú hodiny na stene skutočný miestny čas. Pri hre o skóre a v partii merajú čas hrania od 11:30.' ),
		array( '0.3.2', '4. 11. 2026', 'Menu: tlačidlá Rebríček a Nové rozostavenie sú preč (rebríček je na F8, nové rozostavenie na R a na lište dole). Hrať s priateľom sa volá Poslať výzvu: vyzvaný hráč vidí Boli ste vyzvaný a môže prijať alebo odmietnuť. Hráča sa dá vyzvať na partiu alebo pozvať na spoločný tréning (červený stôl, bez faulov, kto potopí, pokračuje, farby sa vracajú, kým sú na stole červené).' ),
		array( '0.3.1', '4. 11. 2026', 'Tréning je prvá položka menu a hrá sa v tej istej herni na stole s červeným súknom. Hrať (o najlepšie skóre) a Hrať s priateľom ostávajú na zelenom súkne. Tlačidlo Liga je svetlomodré. Registrácia do ligy je červená vizitka na stole v kancelárii (klik ju otvorí, po registrácii je na nej moje meno, krajina a liga). Kým je hráčov málo, hrá každý s každým bez denného limitu.' ),
		array( '0.3.0', '4. 11. 2026', 'Liga: sezóna na rok, štyri ligy (1. liga top 10, 2. liga 11. až 30. miesto, 3. liga 31. až 70. miesto, 4. liga ostatní), každý začína so 147 bodmi, víťaz získa body, ktoré nahral, a porazený ich stratí. Klik na Liga v menu otvorí kanceláriu hráča: registrácia do ligy za stolom (krajina, mesto, prezývka, ruka, obľúbené tágo, o mne), kalendár sezóny a notebook na stole, výsledková tabuľa štyroch líg na stene, mapa sveta s hráčmi, stojan s mojimi tágami (4 do zápasu, vlastný názov, farby, sila a falše). V herni pribudla nástenka Liga (F12). Ligové zápasy na štadióne prídu v ďalšej verzii.' ),
		array( '0.2.9', '4. 11. 2026', 'Keď je biela pri mantineli, tágo sa zdvihne strmšie (až do 40 stupňov), aby neprechádzalo cez mantinel a rám stola. Kamera za tágom sa vtedy zdvihne nad tágo.' ),
		array( '0.2.8', '4. 11. 2026', 'Pri bare (F10) sa dá myšou rozhliadať a kolieskom približovať. Drž Ctrl: myš sa uvoľní a dá sa kliknúť na telefón; so zachytenou myšou stačí pozrieť na telefón a kliknúť. Hra beží aj na vlastnej adrese snooker.hedlajner.sk.' ),
		array( '0.2.7', '4. 11. 2026', 'F10: pohľad z baru. Na barovom stolíku leží telefón s obrazovkou Môj účet a dva poháre s vodou. Klik na telefón (alebo M) ho zväčší na obrazovku so stránkou Môj účet z webu. Pri hre o skóre čas pri bare stojí. Tabuľa so skóre na stene ukazuje aktuálny čas framu.' ),
		array( '0.2.6', '4. 11. 2026', 'V herni pribudlo rádio: retro rádio na komode, pri pravej stene stolík s mixpultom a dva reproduktory na stojanoch. Stanice sú z My Player. Zvuk je priestorový (ľavý a pravý reproduktor, mení sa podľa pohľadu), mixpult mení hlasitosť, basy, výšky a vyváženie, LED stĺpce a membrány idú do rytmu. F9 pošle kameru k mixpultu.' ),
		array( '0.2.5', '4. 11. 2026', 'Kláves F9 je zrušený. Správy sú v pohľade z kresla (F7): vpravo titulky webu Hedlajner a správy z RSS, klik otvorí článok, C a V ich otvoria na celú obrazovku. Z menu ostali preč tlačidlá Tágá, Nápoveda a Skóre (klávesy F2, F1 a F4 fungujú).' ),
		array( '0.2.4', '4. 11. 2026', 'Pri hre o najlepšie skóre sa v kresle (F7) zastaví čas framu aj hodiny na stene. V partii s priateľom čas beží ďalej, lebo môže ťahať súper.' ),
		array( '0.2.3', '4. 11. 2026', 'Čas rozohraného framu a hodiny na stene sa po obnovení stránky (F5) nestratia. Pri hre o najlepšie skóre ukazujú hodiny čas framu (od 11:30), inak celkový čas hrania.' ),
		array( '0.2.2', '4. 11. 2026', 'Menu: Hrať (o najlepšie skóre), Tréning, Hrať s priateľom, Rebríček, Nastavenia; tágá, nápoveda a skóre ostali na F2, F1 a F4. Rozohraný frame sa pamätá, kým neskončí, potom sa sám začne nový. Na konci framu slávnostné ukončenie s konfetami, skóre za čas a miestom v rebríčku. Na zadnej stene herne polica s pohármi pre troch najlepších hráčov a tabuľka 4. až 10. miesta, F8 na ne pošle kameru.' ),
		array( '0.2.1', '4. 11. 2026', 'Prvá položka menu je O najlepšie skóre: jeden hráč hrá celý frame podľa pravidiel, fauly sa odpočítajú, rebríček prihlásených hráčov podľa bodov a pri rovnosti kratšieho celkového času. Rozohraný frame sa pamätá v prehliadači. F8 ukáže rebríček (pohľad na noviny je zrušený, noviny sa čítajú z kresla F7 klávesom C). V pohľade z kresla (F7) koliesko približuje pohľad.' ),
		array( '0.2.0', '4. 11. 2026', 'Hrať môžu len prihlásení: neprihlásený vidí v menu žlté tlačidlo Prihlásiť sa. Nová ponuka Hrať s priateľom: zoznam hráčov, ktorí sú práve v hre, pozvánka a partia cez internet podľa pravidiel snookeru (poradie gúľ, fauly, body, séria, koniec framu). Súper vidí tágo pri mierení, úder sa prehrá u oboch. Partie majú vo WordPresse vlastné tabuľky so záznamom každého úderu, po výpadku internetu sa pokračuje tam, kde sa skončilo, prerušenú partiu možno dokončiť neskôr. Na stene s dverami visia hodiny, ktoré merajú čas hrania od 11:30.' ),
		array( '0.1.26', '4. 11. 2026', 'Na stolíku pribudol časopis so správami z RSS kanálov (My RSS), F9 ho ukáže. Noviny (F8) aj časopis (F9) sa dajú čítať na celú obrazovku (tlačidlo alebo C): karty s fotkami, zdrojom, dátumom a úvodom, klik otvorí článok.' ),
		array( '0.1.25', '4. 11. 2026', 'V pohľade z kresla (F7) sa dá pohybom myši rozhliadať po herni.' ),
		array( '0.1.24', '4. 11. 2026', 'Ctrl sa drží: kým je stlačený, myš je voľná (kurzor, dá sa klikať), po pustení sa znova zachytí na tágo.' ),
		array( '0.1.23', '4. 11. 2026', 'Ctrl uvoľní myš (zobrazí sa kurzor, dá sa klikať na obrazovke, menu sa neotvorí), ďalší Ctrl ju znova zachytí na tágo.' ),
		array( '0.1.22', '4. 11. 2026', 'Konferenčný stolík pred kreslami a na ňom noviny s titulkou webu Hedlajner (rovnaké rubriky ako hlavná stránka, obrázky, dátumy). F7: pohľad z kresla na stôl. F8: čítanie novín, vpravo klikateľné titulky otvoria článok na webe.' ),
		array( '0.1.21', '4. 11. 2026', 'F6 otvorí alebo zatvorí dvere herne: krídlo sa plynulo pohne, pánty vŕzgajú a pri zatvorení dvere buchnú a cvakne zámok.' ),
		array( '0.1.20', '4. 11. 2026', 'Vymenené F3 a F4: F3 kriedovanie, F4 tabuľa so skóre. Pri kriedovaní sa tágo zdvihne nad guľu a odtiahne, krieda je kocka s bielym obalom a štvorcovou dierou s modrou kriedou, nasadí sa na špičku a pootáča sa.' ),
		array( '0.1.19', '4. 11. 2026', 'Šípka smeru gule je jeden kužeľ s medzerou od gule (nedotýka sa jej).' ),
		array( '0.1.18', '4. 11. 2026', 'Tágo je jeden zúžený kus s textúrou dreva. Stojan má 10 tág. Tab: pohľad na stôl zhora. F3: tabuľa so skóre v herni. F4: kriedovanie špičky, potom sú falše 3 údery 5x silnejšie (bez kriedy len pätina účinku). Priehľadná 3D šípka vo farbe gule ukazuje, kam guľa pôjde; detail dotyku ukazuje, odkiaľ prichádza biela a kam pôjde guľa. Obrazy už neblikajú. Všetko je aj na nástenke (F1).' ),
		array( '0.1.17', '4. 11. 2026', 'Väčšia herňa s vybavením a otvorenými dverami do chodby. F1: kamera ukáže nástenku s nápovedou. F2: stojan s 5 tágami (Klubové, Krátke, Mäkké, Dlhé, Majstrovské), výber myšou alebo šípkami. Tágo mení silu úderu, citlivosť ťahania a falše; jemné mierenie so Shift majú len pokročilé a majstrovské tágá.' ),
		array( '0.1.16', '4. 11. 2026', 'Herňa okolo stola: miestnosť 7,5 x 5,5 m so stropom vo výške 3 m, drevené obloženie stien, tmavozelená tapeta, lišty, strop s trámami, 6 nástenných svietidiel. Lampy visia na lankách zo stropu, kamera neprejde cez steny ani strop.' ),
		array( '0.1.15', '4. 11. 2026', 'Posun pohľadu pravým tlačidlom bez mierenej gule sa pozerá na bod pol metra pred bielou v smere mierenia (nie na stred stola).' ),
		array( '0.1.14', '4. 11. 2026', 'Priblíženie kolieskom je rýchlejšie (asi o 20 % na jeden krok) a má väčší rozsah, od pohľadu na celý stôl až tesne k bielej. Mantinely majú prierez ako skutočný stôl: podrezaný spodok, nos vo výške gule a šikmý vrch, žiadna kolmá stena.' ),
		array( '0.1.13', '4. 11. 2026', 'Zrušené prepínanie kamier (Za tágom, Zhora, Voľná a klávesy 1, 2, 3). Hrá sa vždy za tágom, aj keď bola predtým uložená iná kamera.' ),
		array( '0.1.12', '4. 11. 2026', 'Pri posune pohľadu pravým tlačidlom, keď sa nemieri na žiadnu guľu, sa kamera pozerá na stred stola.' ),
		array( '0.1.11', '4. 11. 2026', 'Guľa, na ktorú sa mieri, je zvýraznená pulzujúcim žltým obrysom a krúžkom na súkne.' ),
		array( '0.1.10', '4. 11. 2026', 'Vymenené tlačidlá: pravé tlačidlo posúva pohľad (kamera sa pozerá na mierenú guľu, a keď sa nemieri na žiadnu, na bielu), koliesko posúva miesto úderu, dvojklik kolieskom ho vráti do stredu. Zrušené šípky pri detaile dotyku.' ),
		array( '0.1.9', '3. 11. 2026', 'Pri posúvaní pohľadu kolieskom sa kamera zároveň otáča, aby sa stále pozerala na guľu, na ktorú sa mieri.' ),
		array( '0.1.8', '3. 11. 2026', 'Nový stôl: mantinely so zaoblenými čeľusťami jamiek, rám so zaoblenými rohmi a výrezmi jamiek, kožené lemy, zaoblené teleso stola. Nekonečná podlaha z drevených dosiek, lampy vyššie nad stolom na lankách. Po pustení kolieska sa pohľad vráti na pôvodné miesto.' ),
		array( '0.1.7', '3. 11. 2026', 'Stlačené koliesko myši posúva pohľad hore, dole, doľava a doprava. Po údere kamera sleduje bielu guľu a pohybom myši bez tlačidla sa pohľad otáča okolo nej.' ),
		array( '0.1.6', '3. 11. 2026', 'Krajšie gule: odrazy okolia na lesklom povrchu, spodok gúľ osvetlený odrazom zeleného súkna (už nie je čierny), mäkký tieň v mieste dotyku so súknom.' ),
		array( '0.1.5', '3. 11. 2026', 'Ľavé tlačidlo drž = naťahovanie tága a úder, pravé tlačidlo drž = pohybom myši sa posúva miesto úderu na bielej.' ),
		array( '0.1.4', '3. 11. 2026', 'Myš sa v hre zachytí v okne (nemôže ujsť mimo), uvoľní sa až klávesom Esc, ktorý otvorí hlavné menu. Bielu do ruky posúva pohyb myši, ľavý klik ju položí. Hlavné menu na začiatku hry.' ),
		array( '0.1.3', '3. 11. 2026', 'Myš ako tágo: mieri sa pohybom myši bez tlačidla, ľavé tlačidlo zamkne smer, pravým tlačidlom ruka chytí tágo a strieľa sa pohybom myši dopredu (sila podľa rýchlosti). Mierenie je asi 8x presnejšie, gule sú hladšie.' ),
		array( '0.1.2', '3. 11. 2026', 'Pomocné čiary sú predvolene vypnuté (v hre aj v detaile dotyku). Zapínať sa budú v hlavnom menu.' ),
		array( '0.1.1', '3. 11. 2026', 'Presné mierenie: detail dotyku gúľ zhora pod stolom (uhol, plnosť zásahu, či guľa mieri do jamky), tlačidlá na jemné mierenie. Dá sa vypnúť v Nastaveniach.' ),
		array( '0.1.0', '3. 11. 2026', 'Prvá verzia: 3D stôl, fyzika gúľ s falšami, kamery, ovládanie, zvuky a tréning. Plán vývoja v administrácii.' ),
	);
}
